const e=[{id:1,code:"GOV-101",icon:"DoorOpen",accent:"#2563eb",title:"خطة الإخلاء في حالات الطوارئ",subtitle:"Emergency Evacuation Plans",summary:"إعداد خطة الإخلاء للدوائر والمباني الحكومية",blocks:[{body:"تُعدّ خطة الإخلاء في حالات الطوارئ من أهم الوثائق في أي دائرة حكومية، إذ تحمي حياة الموظفين والمراجعين عند وقوع حوادث مثل الحرائق أو الزلازل أو المخاطر الكيميائية."},{heading:"1. خطوات إعداد الخطة",body:"تتطلب الخطة الناجحة الخطوات الآتية:",points:["المخطط: أعِدّ مخططًا كاملًا للمبنى يبيّن مسارات الإخلاء ومواقع مطفآت الحريق","مسارات الإخلاء: يجب أن يكون لكل طابق مساران للإخلاء على الأقل متباعدان أحدهما عن الآخر (NFPA 101)، ويجب أن تُفتح أبواب الخروج من الداخل دون مفتاح","نقطة التجمع: مكان آمن خارج المبنى، على مسافة موصى بها لا تقل عن 50 مترًا","المسؤولية: حدِّد مسؤولًا عن الإخلاء لكل طابق","نظام الإنذار: جرس أو صفارة إنذار حريق تُسمع في جميع الطوابق","التدريب: تمرين عملي على الإخلاء مرة واحدة كل 3 أشهر"]},{heading:"2. قواعد الإخلاء الآمن",body:"عند انطلاق جرس الإنذار:",points:["تحرّك بهدوء وانتظام — لا تركض","لا تستخدم المصعد — اخرج عبر السلالم فقط","إذا وُجد دخان، فاخفض جسمك وازحف على ركبتيك تحت الدخان","قبل فتح الباب، افحصه بظهر يدك — فإن كان ساخنًا فلا تفتحه وابحث عن مسار آخر","ساعد الأشخاص الذين يحتاجون إلى المساعدة، وأغلق الأبواب خلفك","توجّه مباشرةً إلى نقطة التجمع وابقَ هناك"]},{heading:"3. دور المسؤولين",body:"يحتاج كل طابق إلى مسؤول عن الحريق:",points:["مسؤول الحريق (Fire Warden): المسؤول الرئيسي عن الطابق","تفتيش جميع الغرف (بما فيها دورات المياه والمخازن) للتأكد من عدم بقاء أحد","إرشاد الأشخاص إلى مسارات الإخلاء","عدّ الأشخاص في نقطة التجمع وإبلاغ فريق الدفاع المدني 115"]}],media:[{kind:"image",src:"media/images/gov_evacuation.png",title:"مخطط الإخلاء",description:"نموذج لمخطط إخلاء"}],quiz:[{question:"على أي مسافة يُوصى بأن تبعد نقطة التجمع عن المبنى؟",options:[{text:"10 أمتار",correct:!1},{text:"25 مترًا",correct:!1},{text:"50 مترًا",correct:!0},{text:"100 متر",correct:!1}],explanation:"50 مترًا على الأقل، لتكون بعيدة عن الزجاج والقطع المتساقطة وعن الدخان، ولكي لا تسدّ طريق مركبات الطوارئ."}]},{id:2,code:"GOV-102",icon:"FileLock",accent:"#059669",title:"حماية الوثائق",subtitle:"Document Protection",summary:"إجراءات حماية الوثائق المهمة من الحريق والمياه",blocks:[{body:"الوثائق الحكومية ثروة ثمينة، وقد يؤدي فقدانها بسبب الحريق أو المياه إلى توقف عمل الدائرة وضياع حقوق المواطنين. لذلك فإن حمايتها ونسخها أمر ضروري."},{heading:"1. تصنيف الوثائق",body:"تحديد درجة أهمية الوثائق:",points:["المستوى A — بالغة الأهمية: العقود والوثائق المالية والقانونية","المستوى B — مهمة: التقارير والمراسلات الرسمية","المستوى C — عادية: المراسلات غير الرسمية"]},{heading:"2. الحماية المادية",body:"إجراءات الحماية المادية:",points:["خزائن مقاومة للحريق: لوثائق المستوى A","خزائن معدنية مقفلة، مرفوعة عن الأرض","أكياس وصناديق بلاستيكية مقاومة للماء","التحكم في البيئة: مكان بارد وجاف بدرجة حرارة ورطوبة ثابتتين"]},{heading:"3. قاعدة 3-2-1 للنسخ الاحتياطية (Backup)",body:"قاعدة 3-2-1:",points:["3 نسخ من كل بيانات مهمة","نوعان (2) مختلفان من وسائط التخزين","نسخة واحدة (1) في مكان آخر خارج المبنى"]}],media:[{kind:"image",src:"media/images/gov_backup.png",title:"النسخ الاحتياطية (Backup)",description:"قاعدة 3-2-1"}],quiz:[{question:"ماذا تعني قاعدة 3-2-1؟",options:[{text:"3 حواسيب",correct:!1},{text:"3 نسخ، ونوعان (2) من الوسائط، ونسخة (1) خارج المبنى",correct:!0},{text:"3 أيام",correct:!1},{text:"3 موظفين",correct:!1}],explanation:"3 نسخ على نوعين (2) من الوسائط، ونسخة واحدة (1) في مكان آخر خارج المبنى."}]},{id:3,code:"GOV-103",icon:"Zap",accent:"#ca8a04",title:"السلامة الكهربائية",subtitle:"Electrical Safety",summary:"المخاطر الكهربائية في الدوائر وفحص الأجهزة",blocks:[{body:"تُعدّ الكهرباء من الأسباب الرئيسية لاندلاع الحرائق في الدوائر. ويجب فحص الأسلاك القديمة، وتحميل المقابس فوق طاقتها، وأجهزة التدفئة بصورة منتظمة."},{heading:"1. المخاطر الكهربائية",body:"المخاطر الشائعة في الدوائر:",points:["التحميل الزائد: توصيل أجهزة كثيرة بمقبس واحد","الأسلاك القديمة ذات العوازل المتشققة أو المكسورة","وجود الماء بالقرب من الأجهزة والمقابس الكهربائية","أسلاك التمديد (Extension): استخدامها بكثرة وبصورة دائمة"]},{heading:"2. قواعد السلامة",body:"القواعد اليومية:",points:["لا توصل سلك تمديد بسلك تمديد آخر","يجب أن تكون يداك جافتين قبل لمس المقبس","صِل المدفأة مباشرةً بمقبس الجدار، لا بسلك تمديد"]},{heading:"3. الحريق الكهربائي",body:"إذا اندلع حريق في جهاز كهربائي:",points:["إن استطعت ذلك بأمان، فافصل الكهرباء من اللوحة الكهربائية واتصل بالرقم 115","إذا كان الحريق صغيرًا وكنت مدرَّبًا، فاستخدم مطفأة ثاني أكسيد الكربون (CO₂) أو مطفأة المسحوق الجاف (ABC) وطريق الخروج خلفك؛ وإلا فاخرج","لا تستخدم الماء ولا الرغوة إلا إذا أظهر الملصق تصنيف الفئة C أو علامة اختبار كهربائي — فهناك خطر الصعق الكهربائي"]}],media:[{kind:"video",src:"media/videos/gov_electrical.mp4",title:"السلامة الكهربائية",description:"إرشادات"}],quiz:[{question:"أي مطفأة حريق هي الأفضل للحريق الكهربائي؟",options:[{text:"الماء",correct:!1},{text:"الرغوة",correct:!1},{text:"CO₂ أو المسحوق الجاف",correct:!0},{text:"بطانية",correct:!1}],explanation:"لا يوصل CO₂ والمسحوق الجاف الكهرباء؛ أما الماء والرغوة العاديان فيوصلانها وقد يسببان الصعق الكهربائي."}]},{id:4,code:"GOV-104",icon:"HeartPulse",accent:"#dc2626",title:"برنامج الإسعافات الأولية",subtitle:"First Aid Program",summary:"تشكيل فريق الإسعافات الأولية وتجهيز المستلزمات",blocks:[{body:"تحتاج كل دائرة إلى برنامج للإسعافات الأولية. ويُوصى بوجود شخص مدرَّب واحد على الأقل في كل طابق وفي كل نوبة دوام، وعدد أكبر في الدوائر الكبيرة."},{heading:"1. فريق الإسعافات الأولية",body:"تشكيلة الفريق:",points:["شخص مدرَّب واحد على الأقل في كل طابق وفي كل نوبة دوام","دورة معتمدة في الإسعافات الأولية والإنعاش القلبي الرئوي (CPR) وجهاز إزالة الرجفان الخارجي الآلي (AED)","تجديد التدريب والشهادة كل سنتين"]},{heading:"2. حقيبة الإسعافات الأولية",body:"المستلزمات الضرورية:",points:["ضمادات (Bandage) وشاش نظيف (Gauze)","مواد تطهير الجروح (Antiseptic)","مقص وملقط","قفازات طبية تُستخدم لمرة واحدة","قناع CPR لإعطاء أنفاس الإنقاذ بأمان"]},{heading:"3. الإنعاش القلبي الرئوي (CPR)",body:"خطوات CPR للبالغين:",points:["1. إذا كان الشخص لا يستجيب ولا يتنفس بصورة طبيعية: اتصل بالإسعاف على الرقم 122 واطلب جهاز AED؛ ثم ضعه على ظهره فوق سطح صلب","2. أجرِ 30 ضغطة صدرية في منتصف الصدر: بعمق 5-6 سم، وبمعدل 100-120 ضغطة في الدقيقة","3. أعطِ نَفَسين (مدة كل منهما نحو ثانية واحدة) إذا كنت مدرَّبًا؛ وإلا فاكتفِ بالضغطات الصدرية","4. استمر بنسبة 30:2 حتى وصول جهاز AED أو سيارة الإسعاف؛ واستخدم AED فور وصوله"]}],media:[{kind:"video",src:"media/videos/gov_cpr.mp4",title:"الإنعاش القلبي الرئوي (CPR)",description:"كيفية إجراء CPR"}],quiz:[{question:"في CPR، كم ضغطة صدرية تُجرى قبل النَّفَسين؟",options:[{text:"10",correct:!1},{text:"15",correct:!1},{text:"30",correct:!0},{text:"50",correct:!1}],explanation:"النسبة الصحيحة للبالغين هي 30:2 (AHA 2025)."}]},{id:5,code:"GOV-105",icon:"Flame",accent:"#ea580c",title:"الحريق ومطفآت الحريق في الدوائر",subtitle:"Fire Prevention & Extinguisher Use",summary:"الوقاية من الحرائق واستخدام مطفآت الحريق في المباني الحكومية",blocks:[{body:"يشكّل اندلاع الحرائق في الدوائر خطرًا جديًا. فالورق والحواسيب والأسلاك القديمة والتحميل الكهربائي الزائد هي الأسباب الرئيسية للحرائق. ويحمي برنامج الوقاية والاستعداد حياة الموظفين والمال العام."},{heading:"1. أسباب الحرائق في الدوائر",body:"الأسباب الرئيسية:",points:["التحميل الكهربائي الزائد: توصيل أجهزة كثيرة بمقبس واحد","الورق والوثائق: مواد سريعة الاشتعال","السجائر وأعواد الثقاب: سبب رئيسي لاشتعال الحرائق","المدافئ وأجهزة التدفئة المتنقلة: خطر فصل الشتاء","المطابخ الصغيرة: أثناء إعداد الشاي والقهوة","البطاريات والشواحن: الارتفاع المفرط في درجة الحرارة"]},{heading:"2. أنواع مطفآت الحريق",body:"تحتاج الدوائر إلى الأنواع الآتية:",points:["مطفأة المسحوق الجاف (ABC): لحرائق الفئات A وB وC — وليست للمعادن (D) ولا لزيوت الطبخ (K)","مطفأة CO₂: لحرائق الأجهزة الكهربائية — لا تُلحق ضررًا بالحواسيب","مطفأة الماء: للفئة A فقط (الورق والخشب والملابس) — وليست للكهرباء ولا للزيوت","يوصي الكود البريطاني BS 5306-8 بمطفأتين (2) على الأقل في كل طابق (باستثناء الطوابق الصغيرة جدًا)؛ أما القاعدة الخاصة بدوائر دهوك فتضعها مديرية الدفاع المدني، ولم تُؤكَّد بعدُ","ضع مطفآت الحريق قرب الأبواب وعلى مسارات الإخلاء","فحص بصري شهري (مسمار الأمان والختم سليمان، والملصق مقروء، ومؤشر الضغط في المنطقة الخضراء إن وُجد؛ ومطفأة CO₂ لا مقياس لها، لذا ارفعها لتتأكد من أنها ممتلئة) وفحص وصيانة كل سنة من قِبل شخص مختص (NFPA 10)"]},{heading:"3. طريقة PASS",body:`قبل استخدام المطفأة (يجب أن تكون كل الإجابات «نعم»):
• الحريق صغير وفي بدايته، مثل حريق في سلة مهملات أو مقلاة.
• المطفأة مناسبة لهذا النوع من الحريق.
• طريق الخروج خلفك، والنار ليست بينك وبين المخرج.
• تمّ إطلاق الإنذار: نُبِّه الآخرون واتُّصل بالرقم 115.
• أنت مدرَّب على استخدام المطفأة.
• لا يوجد دخان أو حرارة يمنعان خروجك.
• إذا لم تنطفئ النار فورًا، فتوقّف واخرج وأغلق الباب خلفك.

طريقة PASS هي الطريقة العامة لمعظم مطفآت الحريق اليدوية. أما مطفآت الفئة D والمادة الكيميائية الرطبة (Wet Chemical) والعوامل النظيفة (Clean Agent) والمطفآت ذات العجلات فتُستخدم وفق الملصق وتعليمات الشركة المصنّعة. كيفية استخدام مطفأة الحريق:`,points:["P = Pull (اسحب): اسحب مسمار الأمان وانزعه","A = Aim (وجِّه): وجِّه فوهة الخرطوم (Nozzle) نحو قاعدة النار","S = Squeeze (اضغط): اضغط مقبض المطفأة بقوة","S = Sweep (حرِّك): حرِّك الفوهة عند قاعدة النار من جانب إلى آخر","المسافة: ابدأ من المسافة المحددة على ملصق المطفأة أو في تعليمات الشركة المصنّعة، وطريق الخروج خلفك، ولا تقترب إلا كلما صغرت النار","اترك طريق الخروج خلفك؛ وإذا لم تنطفئ النار فورًا أو بدأت تنتشر، فاخرج وأغلق الباب خلفك وتأكد من الاتصال بالرقم 115"]},{heading:"4. أنظمة الإنذار",body:"الأنظمة الضرورية في الدوائر:",points:["صفارة إنذار الحريق: يجب أن تُسمع في كل طابق","زر الإنذار اليدوي (Pull Station): قرب المخارج","كشف الدخان (Smoke Detection): وفق ما يتطلبه كود الحريق الخاص بالمبنى (Fire Code) (ولم يُؤكَّد بعدُ المتطلب الخاص بدوائر دهوك)","إضاءة الطوارئ: تعمل تلقائيًا عند انقطاع الكهرباء","اكتب الرقم 115 على جدار كل غرفة"]}],media:[{kind:"video",src:"media/videos/gov_fire_prevention.mp4",title:"الوقاية من الحرائق",description:"إرشادات كاملة للدوائر"},{kind:"image",src:"media/images/gov_pass_method.png",title:"طريقة PASS",description:"خطوة بخطوة"},{kind:"image",src:"media/images/gov_extinguisher_types.png",title:"أنواع مطفآت الحريق",description:"ABC، CO₂، الماء"}],quiz:[{question:"أي مطفأة حريق هي الأفضل لحرائق الحواسيب؟",options:[{text:"مطفأة الماء",correct:!1},{text:"مطفأة CO₂",correct:!0},{text:"مطفأة الرغوة",correct:!1},{text:"بطانية",correct:!1}],explanation:"لا تُلحق CO₂ ضررًا بالحواسيب ولا توصل الكهرباء."},{question:"في طريقة PASS، ماذا يعني الحرف A؟",options:[{text:"Alert (التنبيه)",correct:!1},{text:"Aim (وجِّه)",correct:!0},{text:"Action (التنفيذ)",correct:!1},{text:"Away (بعيدًا)",correct:!1}],explanation:"A = Aim: وجِّه فوهة الخرطوم نحو قاعدة النار."},{question:"كم مطفأة حريق على الأقل يوصي بها الكود البريطاني BS 5306-8 في كل طابق؟",options:[{text:"مطفأة واحدة (1)",correct:!1},{text:"مطفأتان (2)",correct:!0},{text:"3 مطفآت",correct:!1},{text:"5 مطفآت",correct:!1}],explanation:"يوصي الكود البريطاني BS 5306-8 بمطفأتين (2) على الأقل في كل طابق (باستثناء الطوابق الصغيرة جدًا)، ويجب ألّا تتجاوز مسافة الوصول إليها الحد المسموح به. أما القاعدة الخاصة بدوائر دهوك فتضعها مديرية الدفاع المدني، ولم تُؤكَّد بعدُ."}]},{id:6,code:"GOV-106",icon:"Activity",accent:"#d97706",title:"الزلازل في المباني الحكومية",subtitle:"Earthquake Safety in Gov Buildings",summary:"كيفية حماية النفس والإخلاء الآمن أثناء الزلزال",blocks:[{body:"يقع إقليم كوردستان في منطقة نشطة زلزاليًا. والمباني الحكومية، ولا سيما القديمة منها، معرّضة للخطر. ويُسهم الاستعداد ومعرفة الإجراءات في إنقاذ الأرواح."},{heading:"1. أثناء الزلزال",body:"إذا كنت داخل الدائرة:",points:["انخفض (Drop): انزل فورًا على ركبتيك ويديك","احتمِ (Cover): ادخل تحت طاولة متينة، بعيدًا عن النوافذ والخزائن الثقيلة (وليس عند المدخل)، واحمِ رأسك ورقبتك","تمسّك (Hold On): أمسك بساق الطاولة حتى يتوقف الاهتزاز","لا تركض نحو الخارج — فكثير من الإصابات تحدث أثناء الركض وبسبب سقوط القطع","لا تستخدم المصعد — فقد يتوقف وتبقى عالقًا فيه","إذا كنت في مكان مفتوح: ابتعد عن المباني وأسلاك الكهرباء والأعمدة"]},{heading:"2. بعد الزلزال",body:"الخطوات بعد الزلزال:",points:["افحص نفسك وزملاءك بحثًا عن إصابات","اخرج عبر السلالم (لا المصعد!)","إذا شممت رائحة غاز أو سمعت صوت تسرّبه: أغلق الغاز من الصمام الرئيسي إن كان ذلك آمنًا، ثم اخرج","توجّه إلى نقطة التجمع وعُدّ الأشخاص","إذا وُجد مصابون أو أشخاص عالقون تحت الأنقاض، فاتصل بالرقمين 115 و122","انتبه إلى الهزات الارتدادية (Aftershocks)","لا تعد إلى داخل المبنى حتى يتأكد المختصون من سلامته"]},{heading:"3. الاستعداد المسبق",body:"التحضيرات الضرورية:",points:["أعِدّ خطة للزلازل وعلّقها على الجدار","ثبّت الخزائن والرفوف والأجهزة الثقيلة بالجدار","جهّز حقيبة طوارئ في كل طابق","فحص المبنى سنويًا من قِبل مهندس مختص","تمرين Drop, Cover, Hold On كل 3 أشهر","حدِّد نقطتَي تجمع (واحدة قريبة وأخرى بعيدة)"]},{heading:"4. مسؤولية المديرين",body:"يجب على المديرين:",points:["تعيين مسؤول عن الزلازل لكل طابق","إبقاء قائمة الموظفين جاهزة لعدّ الأشخاص","وضع خطة خاصة للأشخاص ذوي الاحتياجات الخاصة","فحص نظام الإنذار بصورة منتظمة","كتابة أرقام الطوارئ (115، 122، 104) في كل غرفة"]}],media:[{kind:"video",src:"media/videos/gov_earthquake.mp4",title:"الزلزال في الدائرة",description:"تمرين عملي"},{kind:"image",src:"media/images/gov_drop_cover_hold.png",title:"انخفض، احتمِ، تمسّك (Drop, Cover, Hold On)",description:"خطوة بخطوة"}],quiz:[{question:"أثناء الزلزال، ما أول ما يجب فعله؟",options:[{text:"الركض نحو الخارج",correct:!1},{text:"الدخول إلى المصعد",correct:!1},{text:"Drop, Cover, Hold On",correct:!0},{text:"فتح النوافذ",correct:!1}],explanation:"انخفض تحت طاولة متينة، واحتمِ، وتمسّك حتى يتوقف الاهتزاز."},{question:"بعد الزلزال، ماذا نستخدم للخروج من المبنى؟",options:[{text:"المصعد",correct:!1},{text:"سلالم المبنى",correct:!0},{text:"النوافذ",correct:!1},{text:"لا فرق",correct:!1}],explanation:"اخرج دائمًا عبر السلالم — فقد يتوقف المصعد."},{question:"وفقًا لهذا البرنامج، كم مرة يلزم إجراء تمرين الزلزال في الدائرة؟",options:[{text:"كل سنة",correct:!1},{text:"كل 6 أشهر",correct:!1},{text:"كل 3 أشهر",correct:!0},{text:"مرة واحدة فقط",correct:!1}],explanation:"يوصي هذا البرنامج بإجراء تمرين عملي مرة واحدة كل 3 أشهر."}]},{id:7,code:"GOV-107",icon:"Wind",accent:"#475569",title:"السلامة من الغاز والتهوية",subtitle:"Gas Safety & Ventilation",summary:"مخاطر الغاز في الدوائر وأهمية التهوية السليمة",blocks:[{body:"تُستخدم المدافئ وأجهزة التدفئة العاملة بالغاز والنفط بكثرة في الدوائر خلال فصل الشتاء. وقد يؤدي تسرّب الغاز إلى الانفجار والحريق، كما أن الاحتراق غير الكامل يُنتج غاز أول أكسيد الكربون (CO) السام، وهو غاز عديم اللون والرائحة وقد يكون قاتلًا. والتهوية السليمة ومعرفة المخاطر تُنقذان الأرواح."},{heading:"1. خطر غاز أول أكسيد الكربون (CO)",body:"غاز CO قاتل صامت:",points:["غاز CO عديم اللون والرائحة والطعم — ولا يمكن اكتشافه بالحواس","الأعراض: الصداع، والدوخة، والغثيان والتقيؤ، واضطراب الوعي؛ ثم فقدان الوعي والوفاة","المصدر: مدافئ الغاز والنفط في الغرف غير المهوّاة","الشتاء هو الفصل الأخطر، لأن الأبواب والنوافذ تكون مغلقة","حدّ OSHA للعاملين هو 50 ppm (متوسط 8 ساعات)، لكن يجب أن يكون تركيز CO في غرف العمل قريبًا من الصفر؛ فأي تركيز لغاز CO دليل على نقص التهوية"]},{heading:"2. قواعد التهوية السليمة",body:"التهوية اللازمة في الدوائر:",points:["عند تشغيل مدفأة بلا مدخنة، اترك نافذة مفتوحة قليلًا لدخول الهواء النقي","مروحة تهوية (Ventilation Fan) في الغرف التي توجد فيها مدافئ","أنبوب المدخنة (Chimney): يجب أن يكون سليمًا ومفتوحًا، غير مسدود","لا تسدّ الممرات ومسارات الإخلاء بالمدافئ","أطفئ المدافئ التي بلا مدخنة قبل النوم وعند مغادرة الغرفة، وجدّد هواء الغرفة من وقت لآخر","يجب أن تكون للمطابخ ودورات المياه تهوية خاصة"]},{heading:"3. تسرّب الغاز — ماذا أفعل؟",body:"إذا شممت رائحة غاز:",points:["افتح النوافذ والأبواب فورًا","لا تُشعل أي عود ثقاب ولا تلمس مفاتيح الكهرباء (لا تشغّلها ولا تطفئها)!","لا تستخدم الهاتف المحمول داخل المبنى — فقد تُحدث شرارة واحدة انفجارًا","اخرج وأخرِج جميع الأشخاص","اتصل بالرقم 115 من خارج المبنى","إن استطعت ذلك بأمان، فأغلق الغاز من الصمام الرئيسي"]},{heading:"4. الفحص الشهري",body:"الفحص:",points:["افحص مدخنة المدفأة — يجب ألّا تكون مسدودة","افحص وصلات أنابيب الغاز بالماء والصابون (اختبار الفقاعات)؛ ولا تفحصها بالنار أبدًا","ركّب كاشف CO (Carbon Monoxide Detector)","يفحص فني مختص المدافئ سنويًا","احتفظ بسجل الفحوصات"]}],media:[{kind:"video",src:"media/videos/gov_gas_safety.mp4",title:"خطر الغاز",description:"كيفية الاكتشاف والإجراءات"},{kind:"image",src:"media/images/gov_co_detector.png",title:"كاشف CO",description:"موضع التركيب"}],quiz:[{question:"ما خصائص غاز CO (أول أكسيد الكربون)؟",options:[{text:"له رائحة كريهة",correct:!1},{text:"لونه أحمر",correct:!1},{text:"عديم اللون والرائحة",correct:!0},{text:"ليست له أي خصائص",correct:!1}],explanation:"غاز CO عديم اللون والرائحة والطعم — ولذلك فهو خطير ويلزم جهاز كاشف له."},{question:"إذا شممت رائحة غاز، ما أول ما يجب فعله؟",options:[{text:"تشغيل المصباح الكهربائي",correct:!1},{text:"فتح النوافذ والخروج",correct:!0},{text:"استخدام الهاتف المحمول",correct:!1},{text:"تشغيل المدفأة",correct:!1}],explanation:"افتح النوافذ، ولا تقترب من النار ولا تلمس المفاتيح، واخرج واتصل بالرقم 115 من الخارج."},{question:"متى يجب إطفاء مدفأة الغاز التي بلا مدخنة؟",options:[{text:"فقط عندما ينفد الغاز",correct:!1},{text:"قبل النوم وعند مغادرة الغرفة",correct:!0},{text:"في الصيف فقط",correct:!1},{text:"لا حاجة إلى إطفائها",correct:!1}],explanation:"لا تترك المدافئ التي بلا مدخنة مشتعلة أبدًا أثناء النوم أو عند خلو الغرفة من الأشخاص؛ وجدّد هواء الغرفة من وقت لآخر."}]},{id:8,code:"GOV-108",icon:"Lock",accent:"#0891b2",title:"الأمن السيبراني وحماية البيانات",subtitle:"Cybersecurity & Data Protection",summary:"حماية الأنظمة الحاسوبية والبيانات الحكومية من الهجمات الإلكترونية والفيروسات",blocks:[{body:"في العصر الرقمي، تشكّل الهجمات السيبرانية خطرًا كبيرًا على الدوائر الحكومية. فالبيانات الشخصية للمواطنين والوثائق الرسمية والأنظمة المالية كلها أهداف محتملة. ولذلك فإن استعداد الموظفين وتدريبهم أمر ضروري."},{heading:"1. أنواع المخاطر السيبرانية",body:"المخاطر الرئيسية:",points:["التصيّد الاحتيالي (Phishing): رسائل بريد إلكتروني ورسائل مزيّفة تهدف إلى سرقة المعلومات","الفيروسات والبرامج الضارة (Malware)","برامج الفدية (Ransomware): تشفير البيانات وقفلها والمطالبة بالمال","الهندسة الاجتماعية (Social Engineering): خداع الموظفين للحصول على المعلومات","شبكات WiFi غير المحمية: سرقة المعلومات عبر الشبكة","ذواكر USB المجهولة: قد تنقل الفيروسات"]},{heading:"2. قواعد كلمة المرور (Password)",body:"كلمة المرور القوية:",points:["الطول: 15 حرفًا ورمزًا على الأقل (NIST SP 800-63B-4)","عبارة مرور طويلة مكوّنة من عدة كلمات (Passphrase) يسهل تذكّرها وتكون قوية","لا تغيّر كلمة المرور وفق فترة زمنية محددة؛ بل غيّرها فقط عند الاشتباه في انكشافها","لا تستخدم الاسم أو رقم الهاتف أو 123456","فعِّل التحقق بخطوتين (2FA)","استخدم كلمة مرور مختلفة لكل نظام"]},{heading:"3. البريد الإلكتروني الآمن",body:"كيف تحمي نفسك في البريد الإلكتروني:",points:["لا تفتح الروابط المجهولة — وتحقّق من عنوان المرسِل","لا تفتح المرفقات الواردة من عناوين مجهولة","إذا وصلتك رسالة بريد إلكتروني مشبوهة، فأبلغ قسم تقنية المعلومات (IT)","لا ترسل كلمة المرور أو رقم الحساب المصرفي عبر البريد الإلكتروني","استخدم البريد الإلكتروني الرسمي فقط لأعمال الدائرة"]},{heading:"4. الحماية المادية",body:"حماية الأجهزة:",points:["اقفل حاسوبك عند ابتعادك عن المكتب (Win+L)","لا تسمح للآخرين برؤية المعلومات على شاشتك","لا تُدخل ذواكر USB المجهولة في الحاسوب","أتلِف الأوراق السرية بآلة تمزيق الورق (Shredder)","احمِ هاتف العمل برمز PIN أو ببصمة الإصبع"]}],media:[{kind:"video",src:"media/videos/gov_cybersecurity.mp4",title:"الأمن السيبراني",description:"أسس الحماية"},{kind:"image",src:"media/images/gov_phishing.png",title:"التعرّف على التصيّد الاحتيالي",description:"نماذج لرسائل بريد إلكتروني مزيّفة"}],quiz:[{question:"ما التصيّد الاحتيالي (Phishing)؟",options:[{text:"برنامج مفيد",correct:!1},{text:"رسائل بريد إلكتروني مزيّفة لسرقة المعلومات",correct:!0},{text:"نوع من الحرائق",correct:!1},{text:"نظام للنسخ الاحتياطية",correct:!1}],explanation:"التصيّد الاحتيالي رسائل بريد إلكتروني مزيّفة تبدو كأنها رسمية بهدف سرقة المعلومات."},{question:"كم حرفًا ورمزًا على الأقل يجب أن تتضمن كلمة المرور القوية؟",options:[{text:"4",correct:!1},{text:"6",correct:!1},{text:"8",correct:!1},{text:"15",correct:!0}],explanation:"يشترط المعيار NIST (SP 800-63B-4) لكلمة المرور غير المقترنة بالتحقق بخطوتين (2FA) ما لا يقل عن 15 رمزًا؛ والطول أهم من تنويع الرموز."},{question:"إذا وجدت ذاكرة USB مجهولة على الأرض، فماذا تفعل؟",options:[{text:"أُدخلها في الحاسوب",correct:!1},{text:"أسلّمها إلى مسؤول تقنية المعلومات (IT)",correct:!0},{text:"آخذها إلى المنزل",correct:!1},{text:"لا فرق",correct:!1}],explanation:"قد تحتوي الذواكر المجهولة على فيروسات — فسلّمها إلى قسم تقنية المعلومات (IT)."}]},{id:9,code:"GOV-109",icon:"ShieldAlert",accent:"#7c3aed",title:"الأمن الشخصي والوقاية من العنف",subtitle:"Personal Safety & Workplace Security",summary:"حماية الموظفين من المخاطر الأمنية والعنف في مكان العمل",blocks:[{body:"لا تقتصر سلامة الموظفين على الحريق والكهرباء. فالعنف في مكان العمل والتهديدات والحوادث الأمنية تتطلب الاستعداد أيضًا. ويجب على كل موظف أن يعرف كيف يحمي نفسه في هذه الحالات."},{heading:"1. المخاطر الأمنية في الدوائر",body:"الحالات الأمنية:",points:["المراجعون الغاضبون وغير الراضين","التهديد الجسدي","الطرود والأشياء المشبوهة","الهجوم المسلح أو السرقة أو النهب","احتجاز الرهائن","التهديد عبر الهاتف أو الإنترنت"]},{heading:"2. اهرب، اختبئ، أبلِغ (Run, Hide, Tell)",body:"إذا وقع حادث أمني:",points:["Run (اهرب): إذا كان هناك طريق آمن، فاخرج من المبنى بسرعة","اعرف دائمًا أقرب مسار للخروج","Hide (اختبئ): إذا لم تستطع الهرب، فاختبئ في غرفة واقفل الباب","اجعل هاتفك المحمول صامتًا وأوقف الاهتزاز أيضًا","Tell (أبلِغ): عندما تصبح في مكان آمن، اتصل بالرقم 104 (الشرطة)","أدلِ بجميع المعلومات بدقة: المكان، وعدد الأشخاص، وأوصافهم"]},{heading:"3. التعامل مع المراجعين الغاضبين",body:"أساليب تهدئة الموقف:",points:["تحدّث بصوت هادئ ومنخفض","أصغِ إليه وأظهِر أنك تتفهّم موقفه","حافظ على مسافة آمنة (1.5-2 متر)","أبقِ طريق خروجك مفتوحًا دائمًا","نبِّه أحد زملائك ليأتي لمساعدتك","إذا ساء الموقف، فاضغط زر الطوارئ أو اتصل بالرقم 104"]},{heading:"4. استعداد الدائرة",body:"التحضيرات الأمنية:",points:["تركيب كاميرات المراقبة (CCTV)","نظام التحكم في الدخول (Access Control)","زر الطوارئ (Panic Button) أسفل مكاتب الاستقبال","تدريب الموظفين كل 6 أشهر","تحديث الخطة الأمنية واختبارها","إنشاء اتصال مباشر مع أقرب مركز للشرطة"]}],media:[{kind:"video",src:"media/videos/gov_security.mp4",title:"الأمن الشخصي",description:"اهرب، اختبئ، أبلِغ (Run, Hide, Tell)"},{kind:"image",src:"media/images/gov_deescalation.png",title:"أساليب التهدئة",description:"التعامل مع المراجعين الغاضبين"}],quiz:[{question:"في طريقة Run, Hide, Tell، ما الخطوة الأولى؟",options:[{text:"الاختباء",correct:!1},{text:"الهرب",correct:!0},{text:"المقاومة",correct:!1},{text:"الاتصال بالشرطة",correct:!1}],explanation:"الإجراء الأول: Run (اهرب) إذا كان هناك طريق آمن."},{question:"عند التعامل مع مراجع غاضب، ماذا تفعل؟",options:[{text:"أرفع صوتي أنا أيضًا",correct:!1},{text:"أتحدث بهدوء وأصغي إليه",correct:!0},{text:"أتجاهله",correct:!1},{text:"أغلق الباب في وجهه",correct:!1}],explanation:"تحدّث بهدوء وأصغِ إليه — فهذا يهدّئ الموقف."},{question:"ما رقم الشرطة في إقليم كوردستان؟",options:[{text:"115",correct:!1},{text:"122",correct:!1},{text:"104",correct:!0},{text:"911",correct:!1}],explanation:"الرقم 104 هو رقم الشرطة في إقليم كوردستان."}]},{id:10,code:"GOV-110",icon:"Armchair",accent:"#16a34a",title:"الصحة والسلامة في مكان العمل",subtitle:"Occupational Health & Ergonomics",summary:"حماية صحة الموظفين في مكان العمل والتنظيم السليم للمكتب والكرسي",blocks:[{body:"كثيرًا ما يجلس الموظفون الحكوميون أمام الحاسوب 8 ساعات أو أكثر، مما يسبب آلام الظهر والعينين والكتفين. ويُسهم التنظيم السليم لمكان العمل (Ergonomics) والنشاط البدني في الحفاظ على صحة العاملين."},{heading:"1. تنظيم المكتب والكرسي (Ergonomics)",body:"مكان العمل السليم:",points:["الكرسي: يجب أن يدعم الظهر؛ واضبط ارتفاعه بحيث تستقر القدمان بالكامل على الأرض","الشاشة: يكون أعلاها بمستوى العينين أو أدنى قليلًا، وعلى مسافة 50-70 سم","لوحة المفاتيح: يكون المرفقان بزاوية تقارب 90°","الفأرة: قريبة من لوحة المفاتيح وبالمستوى نفسه","ارتفاع المكتب: يجب أن يتناسب مع طول قامتك","الإضاءة: يجب ألّا يسقط الضوء مباشرةً على الشاشة"]},{heading:"2. حماية العينين",body:"إجهاد العين الناتج عن الشاشات (Computer Vision Syndrome):",points:["قاعدة 20-20-20: كل 20 دقيقة، انظر لمدة 20 ثانية إلى شيء يبعد 20 قدمًا (نحو 6 أمتار)","ارمش كثيرًا — فأمام الشاشة يقلّ رمش العينين فتجفّان","خفّف سطوع الشاشة في المساء","فعِّل الوضع الليلي (Night Mode)","النظارات المضادة للضوء الأزرق (Blue Light) ليس لها أي فائدة مثبتة (AAO)؛ وإذا أصيبت عيناك بالجفاف أو الإجهاد، فراجع طبيب العيون","افحص عينيك سنويًا"]},{heading:"3. آلام الظهر والكتفين",body:"الوقاية والعلاج:",points:["انهض كل 45 دقيقة وتحرّك قليلًا","تمديد الرقبة: أمِل رأسك ببطء نحو كل كتف","تمديد الظهر: أدِر جسمك ببطء وأنت جالس على الكرسي","استخدم السلالم بدلًا من المصعد متى كان ذلك مناسبًا","اشرب الماء بانتظام طوال اليوم","الجلوس الصحيح: ظهر مستقيم، وكتفان مسترخيتان، وقدمان على الأرض"]},{heading:"4. الصحة النفسية",body:"السلامة النفسية للموظفين:",points:["ضغط العمل (Stress): تعرّف على أسبابه الرئيسية","تنظيم الوقت: افصل بين وقت العمل ووقت الراحة","الحديث: تحدّث مع زملائك عن المشكلات","خذ استراحة لمدة 15 دقيقة في الهواء الطلق كل يوم","لا تستخدم هاتفك لأعمال الوظيفة أثناء الاستراحة","إذا استمرت الأعراض: تواصل مع مختص في الصحة النفسية"]}],media:[{kind:"video",src:"media/videos/gov_ergonomics.mp4",title:"بيئة العمل المريحة (Ergonomics)",description:"تنظيم المكتب والكرسي"},{kind:"image",src:"media/images/gov_posture.png",title:"الجلوس الصحيح",description:"صورة إرشادية"},{kind:"image",src:"media/images/gov_eye_care.png",title:"قاعدة 20-20-20",description:"حماية العينين"}],quiz:[{question:"ما الغرض من قاعدة 20-20-20؟",options:[{text:"حماية الأذنين",correct:!1},{text:"حماية العينين",correct:!0},{text:"حماية الظهر",correct:!1},{text:"حماية اليدين",correct:!1}],explanation:"كل 20 دقيقة، انظر لمدة 20 ثانية إلى شيء يبعد 20 قدمًا (نحو 6 أمتار) — لحماية العينين (AAO)."},{question:"على أي مسافة من العينين يجب أن تكون شاشة الحاسوب؟",options:[{text:"20-30 سم",correct:!1},{text:"30-40 سم",correct:!1},{text:"50-70 سم",correct:!0},{text:"1 متر",correct:!1}],explanation:"المسافة الأنسب هي 50-70 سم (نحو طول الذراع)."},{question:"كل كم دقيقة ينبغي للموظف أن ينهض عن مكتبه ويتحرك؟",options:[{text:"20 دقيقة",correct:!1},{text:"45 دقيقة",correct:!0},{text:"ساعتان (2)",correct:!1},{text:"ساعة واحدة (1)",correct:!1}],explanation:"يُوصى بأن تنهض كل 45 دقيقة وتتحرك قليلًا."}]},{id:11,code:"GOV-111",icon:"Waves",accent:"#2563eb",title:"الفيضانات والأضرار الناجمة عن المياه",subtitle:"Flood Response & Water Damage",summary:"الاستعداد للفيضانات وأضرار المياه في الدوائر والاستجابة لها",blocks:[{body:"قد تصل المياه إلى الدوائر من عدة مصادر: الأمطار والسيول الطبيعية، أو انفجار أنابيب المياه، أو أعطال منظومة التكييف، أو تسرّب المياه من الطابق العلوي. ويُسهم الاستعداد والوعي في تقليل الأضرار."},{heading:"1. مصادر المياه في الدوائر",body:"من أين تأتي المياه:",points:["الأمطار والسيول الطبيعية: ولا سيما في المناطق المنخفضة","انفجار أنابيب المياه: الأنابيب القديمة والصدئة","ذوبان الثلوج: يتحول الثلج إلى ماء ويتسرب إلى داخل المبنى","تسرّب المياه من الطابق العلوي: من دورات المياه والمطبخ","منظومة التكييف: تجمّع المياه وتسرّبها","خزانات المياه: انفجار الخزان أو تسرّبه"]},{heading:"2. قبل الفيضان — الاستعداد",body:"التحضيرات الضرورية:",points:["احفظ الوثائق المهمة في الطوابق العليا وفي الخزائن المرتفعة","لا تضع الحواسيب على الأرض — بل ارفعها 30 سم على الأقل عن الأرض","يجب ألّا تكون أسلاك الكهرباء ممددة على الأرض","اعرف مخطط الأنابيب وموقع صمام المياه الرئيسي","جهّز مضخة لسحب المياه (Sump Pump)","أبقِ قائمة أرقام الفنيين والطوارئ جاهزة"]},{heading:"3. أثناء الفيضان",body:"إذا دخلت المياه إلى الدائرة:",points:["إذا لم تكن واقفًا في الماء واستطعت الوصول إلى المفتاح بأمان، فافصل التيار الكهربائي الرئيسي — فاجتماع الكهرباء والماء قاتل","اتصل بالرقم 115 وأبلغ مسؤول المبنى","يتوجه جميع الموظفين بأمان إلى مكان مرتفع","إذا كان منسوب المياه منخفضًا: انقل الوثائق والحواسيب إلى مكان مرتفع","لا تدخل مياه الفيضان: فـ15 سم من المياه الجارية بسرعة قد تُسقط الإنسان، و30 سم قد تجرف السيارة؛ وهناك أيضًا خطر الكهرباء والأمراض","أغلق صمام المياه الرئيسي"]},{heading:"4. بعد الفيضان",body:"بعد انحسار المياه:",points:["فحص المبنى: يجب أن يفحص المختصون المبنى قبل العودة إليه","لا تُعِد تشغيل الكهرباء حتى يتأكد الفني من أنها آمنة","التطهير (Disinfection): مياه الفيضان ملوثة وتنقل البكتيريا والأمراض","التهوية: افتح جميع النوافذ والأبواب","التقط صورًا للتوثيق ولأغراض التأمين","أزِل الأشياء المتضررة بأمان"]}],media:[{kind:"video",src:"media/videos/gov_flood_response.mp4",title:"الاستجابة للفيضان",description:"ماذا نفعل عند دخول المياه"},{kind:"image",src:"media/images/gov_flood_prep.png",title:"الاستعداد للفيضان",description:"خطوة بخطوة"}],quiz:[{question:"عند حدوث فيضان في الدائرة، ما أول ما يجب فعله؟",options:[{text:"جمع الوثائق",correct:!1},{text:"فصل التيار الكهربائي الرئيسي (إن كان ذلك آمنًا)",correct:!0},{text:"التقاط الصور",correct:!1},{text:"التحدث بالهاتف",correct:!1}],explanation:"اجتماع الكهرباء والماء يشكّل خطرًا على الحياة. فإذا لم تكن واقفًا في الماء واستطعت الوصول إلى المفتاح بأمان، فافصل التيار الكهربائي الرئيسي فورًا؛ وإلا فاخرج واتصل بالرقم 115."},{question:"أين نحفظ الوثائق المهمة في دائرة معرّضة لخطر الفيضان؟",options:[{text:"على الأرض",correct:!1},{text:"في الطابق السفلي",correct:!1},{text:"في الطوابق العليا وفي الخزائن المرتفعة",correct:!0},{text:"لا فرق",correct:!1}],explanation:"احفظ الوثائق المهمة دائمًا في مكان مرتفع وآمن."},{question:"لماذا يلزم التطهير بعد الفيضان؟",options:[{text:"من أجل رائحة طيبة",correct:!1},{text:"لأن مياه الفيضان تنقل البكتيريا والأمراض",correct:!0},{text:"من أجل المظهر الجميل",correct:!1},{text:"لا يلزم",correct:!1}],explanation:"مياه الفيضان شديدة التلوث وتنقل البكتيريا والأمراض."}]},{id:12,code:"GOV-112",icon:"FlaskConical",accent:"#65a30d",title:"المواد الكيميائية ومواد التنظيف",subtitle:"Chemical Safety & Cleaning Agents",summary:"الاستخدام الآمن لمواد التنظيف والمواد الكيميائية في الدوائر",blocks:[{body:"تستخدم الدوائر الحكومية أنواعًا كثيرة من مواد التنظيف. وقد يؤدي خلط بعض هذه المواد إلى تكوّن غازات سامة وخطرة. ومعرفة هذه المواد واستخدامها بصورة صحيحة يُنقذان الأرواح."},{heading:"1. المواد الخطرة في الدوائر",body:"توجد هذه المواد في كثير من الدوائر:",points:["مبيّض الكلور (Bleach): لتنظيف دورات المياه — وإذا خُلط بحمض أو بالأمونيا كوّن غازات سامة","الأمونيا: لتنظيف النوافذ — تضر بالجهاز التنفسي","الأحماض: لإزالة الترسبات الكلسية — تحرق الجلد","حبر الطابعات (Toner): مسحوق ناعم — يشكّل خطرًا على الرئتين","سائل تصحيح الكتابة (Correction Fluid): قابل للاشتعال وأبخرته ضارة","حمض البطاريات: يسبب حروقًا كيميائية"]},{heading:"2. قاعدة عدم الخلط!",body:"لا تخلط هذه المواد أبدًا:",points:["الكلور + الأمونيا = غاز الكلورامين (سام وقاتل)","الكلور + الحمض = غاز الكلور (سام وقاتل)","الكلور + الخل (وهو حمض) = غاز الكلور","استخدم كل مادة على حدة","خفِّفها بالماء فقط وفق التعليمات المدوّنة على العبوة — لا بمادة أخرى","اقرأ دائمًا التعليمات المدوّنة على ملصق العبوة (Label)"]},{heading:"3. معدات الحماية الشخصية (PPE)",body:"معدات الحماية عند استخدام المواد:",points:["القفازات: ضرورية مع جميع المواد الكيميائية","الكمامة: عند استخدام الكلور والمواد ذات الروائح النفّاذة","النظارات الواقية: للأحماض والبخاخات","ملابس الحماية: للمواد القوية","إذا لامست المادة الجلد أو العينين: اغسلها بالماء الجاري مدة 20 دقيقة على الأقل؛ وإذا حدث حرق أو تسمم، فاتصل بالرقم 122","التهوية: افتح النافذة أثناء التنظيف"]},{heading:"4. تخزين المواد والتخلص منها",body:"قواعد تخزين المواد:",points:["احفظها في مكان مقفل","بعيدًا عن أشعة الشمس والحرارة","اكتب اسم المادة على جميع القوارير والعبوات","أبقِ صحائف بيانات السلامة (SDS) جاهزة","تخلّص من المواد منتهية الصلاحية بالطريقة الصحيحة — ولا تسكبها في مجاري الصرف الصحي","احفظها بعيدًا عن الطعام ومياه الشرب"]}],media:[{kind:"video",src:"media/videos/gov_chemical_safety.mp4",title:"السلامة الكيميائية",description:"الاستخدام الصحيح"},{kind:"image",src:"media/images/gov_mixing_danger.png",title:"خطر الخلط",description:"المواد التي يجب ألّا تُخلط"},{kind:"image",src:"media/images/gov_ppe_cleaning.png",title:"PPE للتنظيف",description:"معدات الحماية"}],quiz:[{question:"ماذا يحدث إذا خلطنا الكلور بالأمونيا؟",options:[{text:"يتكوّن منظّف أفضل",correct:!1},{text:"يتكوّن غاز الكلورامين (السام)",correct:!0},{text:"لا يحدث شيء",correct:!1},{text:"تتكوّن رائحة طيبة",correct:!1}],explanation:"خلط الكلور بالأمونيا يُكوّن غاز الكلورامين — وفي ذلك خطر على الحياة."},{question:"إذا لامست مادة كيميائية الجلد، فماذا نفعل؟",options:[{text:"نمسحها بمنديل",correct:!1},{text:"نغسلها بالماء مدة 20 دقيقة على الأقل",correct:!0},{text:"نضع عليها كريمًا",correct:!1},{text:"لا نفعل شيئًا",correct:!1}],explanation:"اغسلها فورًا بالماء الجاري مدة 20 دقيقة على الأقل وانزع الملابس الملوثة؛ وإذا حدث حرق، فاتصل بالرقم 122."},{question:"أين نحفظ مواد التنظيف في الدائرة؟",options:[{text:"على المكتب",correct:!1},{text:"قرب الطعام",correct:!1},{text:"في مكان مقفل وبعيد عن الحرارة",correct:!0},{text:"لا فرق",correct:!1}],explanation:"احفظها في مكان مقفل، بعيدًا عن الحرارة والطعام."}]},{id:13,code:"GOV-113",icon:"ArrowUpDown",accent:"#4f46e5",title:"السلامة في المصاعد والسلالم",subtitle:"Elevator & Stairway Safety",summary:"الاستخدام الآمن للمصعد والوقاية من السقوط على السلالم",blocks:[{body:"تُعدّ المصاعد والسلالم من الأماكن التي تكثر فيها الحوادث في المباني الحكومية. فالسقوط على السلالم من أكثر حوادث العمل شيوعًا، كما أن الاحتجاز داخل المصعد حالة خطيرة. ومعرفة القواعد تقلل من الخطر."},{heading:"1. السلامة في المصعد",body:"قواعد استخدام المصعد:",points:["إذا تأخر المصعد، فاصبر — ولا تضغط الزر مرات كثيرة","لا تفتح باب المصعد يدويًا — دعه يُفتح تلقائيًا","لا تتجاوز الحمولة المسموح بها (المكتوبة عليه)","لا تستخدمه أثناء انقطاع الكهرباء","لا تستخدمه أثناء الحريق والزلزال — استخدم السلالم فقط","اعرف مكان زر الطوارئ"]},{heading:"2. الاحتجاز داخل المصعد",body:"إذا احتُجزت داخل المصعد:",points:["حافظ على هدوئك — لا تخف","اضغط زر الطوارئ","استخدم هاتف الطوارئ داخل المصعد","إذا توفرت تغطية لشبكة الهاتف المحمول، فاتصل بالرقم 115","لا تحاول فتح الباب أو الخروج — فذلك خطير","انتظر حتى يصل الفني أو فريق 115 — فالهواء داخل المصعد لا ينفد"]},{heading:"3. السلامة على السلالم",body:"الوقاية من السقوط على السلالم:",points:["أمسك دائمًا بالدرابزين (Handrail)","انظر أمام قدميك — ولا تستخدم الهاتف المحمول","درجة بعد درجة — لا تقفز","امشِ بحذر على السلالم المبللة","عند حمل الأغراض، أبقِ يدًا حرة للإمساك بالدرابزين","يجب أن تكون إضاءة السلالم جيدة — استبدل المصابيح التالفة"]},{heading:"4. الفحص والصيانة",body:"الفحوصات المنتظمة:",points:["المصعد: صيانة شهرية من قِبل شركة مختصة، وفحص سنوي من قِبل جهة معتمدة","علّق شهادة الفحص داخل المصعد","افحص إضاءة الطوارئ على السلالم","أصلِح الدرجات المكسورة فورًا","ضع علامات تحذيرية في الأماكن الزلقة","أبقِ السلالم نظيفة — ولا تترك أي أغراض عليها"]}],media:[{kind:"video",src:"media/videos/gov_elevator_safety.mp4",title:"السلامة في المصعد",description:"الاستخدام الصحيح والاحتجاز داخله"},{kind:"image",src:"media/images/gov_stair_safety.png",title:"السلامة على السلالم",description:"قواعد الوقاية من السقوط"}],quiz:[{question:"أثناء الحريق، ماذا نستخدم للخروج؟",options:[{text:"المصعد",correct:!1},{text:"سلالم المبنى",correct:!0},{text:"لا فرق",correct:!1},{text:"النوافذ",correct:!1}],explanation:"لا تستخدم المصعد أبدًا أثناء الحريق والزلزال — اخرج عبر السلالم فقط."},{question:"إذا احتُجزت داخل المصعد، فماذا تفعل؟",options:[{text:"أحاول فتح الباب",correct:!1},{text:"أصرخ بخوف",correct:!1},{text:"أضغط زر الطوارئ وأحافظ على هدوئي",correct:!0},{text:"أقفز",correct:!1}],explanation:"حافظ على هدوئك واضغط زر الطوارئ، ولا تحاول فتح الباب."},{question:"للوقاية من السقوط على السلالم، ماذا نفعل؟",options:[{text:"نقفز",correct:!1},{text:"نستخدم الهاتف المحمول",correct:!1},{text:"نمسك بالدرابزين وننظر أمام أقدامنا",correct:!0},{text:"نغمض أعيننا",correct:!1}],explanation:"أمسك دائمًا بالدرابزين وانظر أمام قدميك."}]},{id:14,code:"GOV-114",icon:"Network",accent:"#e11d48",title:"إدارة الأزمات",subtitle:"Crisis Management & ICS",summary:"تشكيل فريق إدارة الأزمات ونظام قيادة الحوادث (ICS)",blocks:[{body:"يجب أن يكون لكل دائرة حكومية فريق لإدارة الأزمات (Crisis Management Team). وقد تكون الأزمة حريقًا أو زلزالًا أو فيضانًا أو هجومًا أمنيًا أو حتى هجومًا سيبرانيًا. ويُعدّ نظام قيادة الحوادث (ICS) أداة دولية لإدارة أي حادث."},{heading:"1. فريق إدارة الأزمات (CMT)",body:"تشكيلة الفريق:",points:["رئيس الفريق (Crisis Commander): صاحب القرار والموجِّه","مسؤول العمليات (Operations): تنظيم الأنشطة","مسؤول الاتصال والإعلام: التواصل مع الجهات الخارجية ووسائل الإعلام","مسؤول الدعم اللوجستي: المستلزمات والمعدات","مسؤول البيانات: توثيق الأحداث","مسؤول الإسعافات الأولية: مساعدة المصابين"]},{heading:"2. نظام قيادة الحوادث (ICS)",body:"ICS (Incident Command System):",points:["طُوِّر في الولايات المتحدة الأمريكية، ويُستخدم الآن في دول كثيرة","قائد واحد للحادث — وتسلسل القيادة واضح","تحديد المهام: يعرف كل شخص مهمته ويتبع مشرفًا واحدًا","اتصال موحَّد: قناة اتصال واحدة ولغة بسيطة","تنظيم مرن (Modular): يتوسّع الهيكل أو يتقلّص بحسب حجم الحادث","التقارير: تحديث التقارير في أوقات محددة"]},{heading:"3. خطوات الاستجابة للأزمة",body:"الإجراء العام:",points:["1. الإنذار: فعِّل نظام الإنذار","2. التقييم: اعرف ما الذي حدث وما حجمه","3. التفعيل: اجمع فريق CMT","4. الإدارة: اتخذ القرارات ونفّذها","5. الاتصال: أبلغ جميع الجهات المعنية","6. التعافي: نفِّذ خطة العودة إلى العمل الطبيعي"]},{heading:"4. التدريب والاختبار",body:"الاستعداد المستمر:",points:["تمرين مكتبي (Tabletop Exercise) كل 3 أشهر","تمرين شامل (Full-Scale Drill) كل 6 أشهر","تحديث خطة الأزمات سنويًا","اختبار نظام الاتصال","التنسيق مع الدفاع المدني (115) والشرطة (104)","أجرِ تقييمًا بعد كل تمرين وحسِّن الأداء"]}],media:[{kind:"video",src:"media/videos/gov_crisis_management.mp4",title:"إدارة الأزمات",description:"نظام ICS وفريق CMT"},{kind:"image",src:"media/images/gov_ics_chart.png",title:"مخطط ICS",description:"هيكل القيادة"}],quiz:[{question:"في نظام ICS، كم عدد قادة الحادث؟",options:[{text:"3",correct:!1},{text:"5",correct:!1},{text:"1 (واحد)",correct:!0},{text:"10",correct:!1}],explanation:"في ICS يوجد قائد واحد للحادث، ليكون تسلسل القيادة واضحًا. وإذا شاركت عدة جهات، تعمل القيادة الموحَّدة (Unified Command) وفق خطة واحدة."},{question:"وفقًا لهذا البرنامج، كم مرة يلزم إجراء التمرين المكتبي (Tabletop)؟",options:[{text:"كل سنة",correct:!1},{text:"كل 6 أشهر",correct:!1},{text:"كل 3 أشهر",correct:!0},{text:"مرة واحدة فقط",correct:!1}],explanation:"يوصي هذا البرنامج بإجراء تمرين مكتبي كل 3 أشهر."},{question:"ما الخطوة الأولى في الاستجابة للأزمة؟",options:[{text:"الإدارة",correct:!1},{text:"الاتصال",correct:!1},{text:"الإنذار وتفعيل نظام الإنذار",correct:!0},{text:"التعافي",correct:!1}],explanation:"الخطوة الأولى: الإنذار — فعِّل نظام الإنذار."}]},{id:15,code:"GOV-115",icon:"Megaphone",accent:"#c026d3",title:"الاتصال في حالات الطوارئ",subtitle:"Emergency Communication",summary:"نظام الاتصال والإنذار أثناء الحوادث",blocks:[{body:"أثناء الحوادث، يُنقذ الاتصال الصحيح والسريع الأرواح. ففي كثير من الحوادث، أدّى غياب الاتصال الجيد إلى زيادة عدد الضحايا. ويجب أن يكون لكل دائرة حكومية نظام اتصال قوي."},{heading:"1. أنظمة الإنذار",body:"توجد عدة أنظمة:",points:["صفارة الإنذار الداخلية: جرس الحريق والطوارئ","نظام مكبرات الصوت (PA System): لبث الرسائل إلى جميع الطوابق","الرسائل النصية الجماعية (SMS Group): للموظفين","البريد الإلكتروني العاجل: للتبليغات الرسمية","مجموعات واتساب وتيليغرام: للتنسيق السريع","أجهزة اللاسلكي ثنائية الاتجاه (Walkie-Talkie): لفريق الطوارئ"]},{heading:"2. سلسلة الاتصال",body:"من يرسل الرسالة:",points:["1. المبلِّغ: الشخص الذي شاهد الحادث — يتصل فورًا بالرقم 115 (وبالرقم 122 إذا وُجد مصابون)","2. مسؤول الطابق: الموظف المسؤول عن الطابق والغرف","3. قائد الأزمة: اتخاذ القرار والتوجيه","4. مسؤول الاتصال: التواصل مع 115 والجهات الخارجية","5. مدير الدائرة: إبلاغ المستوى الأعلى","يجب أن تكون جميع الرسائل دقيقة وأن تتضمن معلومات كاملة"]},{heading:"3. محتوى رسالة الطوارئ",body:"تتضمن الرسالة الجيدة ما يأتي:",points:["المكان: أين وقع الحادث (المبنى، الطابق، الغرفة)","ماذا: ما الذي حدث (حريق، زلزال، هجوم...)","الأشخاص: كم شخصًا أُصيب أو بقي في المكان","الخطر: هل يوجد خطر مستمر؟","الاحتياجات: ما المساعدة المطلوبة","الاتصال: رقم هاتفك للتواصل معك"]},{heading:"4. الاتصال بالجهات الخارجية",body:"التواصل مع الجهات الخارجية:",points:["115 — الدفاع المدني: الحرائق والإنقاذ","122 — الإسعاف: الإصابات والحالات المرضية","104 — الشرطة: الحالات الأمنية","وسائل الإعلام: يتحدث مسؤول الاتصال وحده","عائلات الموظفين: إبلاغها بأيسر الطرق","المديرية العامة: التقرير الرسمي"]},{heading:"5. اختبار النظام",body:"الفحص المستمر:",points:["اختبر صفارة الإنذار الداخلية كل شهر","أرسل رسالة تجريبية إلى المجموعة كل أسبوع","افحص بطاريات أجهزة اللاسلكي ثنائية الاتجاه ومداها","حدِّث قائمة أرقام الطوارئ","قيِّم نظام الاتصال بعد كل تمرين","الخطة البديلة: إذا تعطّل أحد الأنظمة، فما البديل؟"]}],media:[{kind:"video",src:"media/videos/gov_emergency_comm.mp4",title:"الاتصال في حالات الطوارئ",description:"نظام الاتصال وسلسلته"},{kind:"image",src:"media/images/gov_comm_chain.png",title:"سلسلة الاتصال",description:"من يتصل بمن"},{kind:"image",src:"media/images/gov_message_template.png",title:"نموذج رسالة",description:"محتوى الرسالة الصحيحة"}],quiz:[{question:"أثناء الطوارئ، ما أسرع نظام لإبلاغ جميع الطوابق؟",options:[{text:"البريد الإلكتروني",correct:!1},{text:"واتساب",correct:!1},{text:"نظام مكبرات الصوت (PA)",correct:!0},{text:"الرسالة الورقية",correct:!1}],explanation:"نظام PA هو الأسرع لأنه يُسمع فورًا في جميع الطوابق."},{question:"ما المعلومات التي يجب أن تتضمنها رسالة الطوارئ؟",options:[{text:"المكان فقط",correct:!1},{text:"عدد المصابين فقط",correct:!1},{text:"المكان، وما الذي حدث، والأشخاص، والخطر، والاحتياجات",correct:!0},{text:"الرقم 115 فقط",correct:!1}],explanation:"الرسالة الكاملة: المكان + ما الذي حدث + الأشخاص + الخطر + الاحتياجات + رقم التواصل."},{question:"أثناء الأزمة، من المخوَّل بالتحدث إلى وسائل الإعلام؟",options:[{text:"أي موظف",correct:!1},{text:"مسؤول الاتصال فقط",correct:!0},{text:"المراجع",correct:!1},{text:"الشرطة فقط",correct:!1}],explanation:"مسؤول الاتصال وحده هو المخوَّل بالتحدث إلى وسائل الإعلام، لكي لا تنتشر معلومات خاطئة."}]},{id:16,code:"GOV-116",icon:"Heart",accent:"#db2777",title:"الإسعافات الأولية والإنعاش القلبي الرئوي (CPR)",subtitle:"First Aid & CPR — Complete Training",summary:"تدريب شامل على الإسعافات الأولية والإنعاش القلبي الرئوي (CPR) والاستجابة للطوارئ في الدوائر",blocks:[{body:"الإسعافات الأولية (First Aid) هي المساعدة الأولية التي تُقدَّم للمصاب أو المريض قبل وصول الفرق الطبية. وفي الدوائر توجد مخاطر الحريق والزلازل والحالات المرضية المفاجئة. ويجب على كل موظف أن يعرف كيف يُجري CPR، ويوقف النزيف، ويحمي المصاب حتى وصول سيارة الإسعاف (122)."},{heading:"1. الإنعاش القلبي الرئوي (CPR)",body:"الإنعاش القلبي الرئوي (CPR) إجراء لإنقاذ الحياة عند توقف قلب الإنسان أو تنفسه:",points:["1. سلامة المكان: هل المكان آمن؟ (لا كهرباء ولا نار ولا غاز؟)","2. الاستجابة: هزّ كتفيه برفق واسأله بصوت عالٍ: «هل أنت بخير؟ هل تسمعني؟»","3. اتصل بالرقم 122: إذا لم يستجب ولم يتنفس بصورة طبيعية، فاتصل فورًا بالرقم 122 وأحضِر جهاز إزالة الرجفان الخارجي الآلي (AED) أو اطلب إحضاره","4. الضغطات الصدرية: 30 ضغطة في منتصف الصدر — بعمق 5-6 سم، وبمعدل 100-120 ضغطة في الدقيقة","5. التنفس: أمِل الرأس إلى الخلف وارفع الذقن، وأغلق فتحتَي الأنف وأعطِ نَفَسين (2) مدة كل منهما ثانية واحدة؛ وإذا لم تتلقَّ تدريبًا، فاكتفِ بالضغطات الصدرية","6. الاستمرار (30:2): حتى يصل فريق الإسعاف (122)","7. جهاز AED: إن وُجد، فشغّله وضع الوسادتين اللاصقتين على الصدر العاري واتبع التعليمات الصوتية"]},{heading:"2. إيقاف النزيف",body:"قد يؤدي النزيف الشديد إلى الوفاة بسرعة:",points:["الضغط المباشر: ضع قطعة قماش نظيفة على الجرح واضغط بقوة ومن دون توقف؛ وإذا تشبّع القماش بالدم فلا تنزعه — بل ضع قطعة أخرى فوقه","حشو الجرح (Wound Packing): إذا كان الجرح عميقًا (كما في الفخذ أو الإبط أو الرقبة)، فاحشُ الجرح بالشاش النظيف واضغط بقوة","الرباط الضاغط (Tourniquet): استخدمه مبكرًا في النزيف الخطير من الذراع أو الساق، على بُعد 5-7 سم فوق الجرح؛ ودوِّن وقت وضعه ولا ترخِه أبدًا","الجسم المنغرس: إذا كانت قطعة حديد أو زجاج داخل الجرح — فلا تنزعها! ثبّتها من حولها واتصل بالرقم 122"]},{heading:"3. علاج الحروق",body:"تحدث الحروق في الدوائر بسبب الحرارة والمواد الكيميائية والكهرباء:",points:["الحروق الحرارية: صُبّ ماءً باردًا جاريًا (لا الثلج!) على الحرق مدة 20 دقيقة","الحروق الكيميائية: اغسلها بكمية كبيرة من الماء الجاري مدة 20 دقيقة","الحروق الكهربائية: افصل الكهرباء أولًا! ثم برِّد الحرق كما في الحروق الحرارية واتصل بالرقم 122","لا تفقأ فقاعات الحرق؛ ولا تستخدم الزيت أو المراهم أو معجون الأسنان"]},{heading:"4. الكسور وإصابات العمود الفقري",body:"عند السقوط:",points:["التجبير (Splinting): لا تحرّك العضو المصاب — بل ثبّته بقطعة خشب أو كرتون","حماية العمود الفقري: إذا سقط شخص من مكان مرتفع — فلا تحرّكه! واتصل بالرقم 122","التبريد: لُفّ الثلج بقطعة قماش وضعه على موضع الألم (لا تضعه مباشرةً على الجلد)"]},{heading:"5. الصعق الكهربائي",body:"قد تؤدي الكهرباء إلى توقف القلب:",points:["افصل الكهرباء فورًا! ولا تلمس المصاب حتى تُفصل الكهرباء","إذا لم تستطع فصل الكهرباء وكانت كهرباء المبنى العادية (جهد منخفض): أبعِد السلك عنه بقطعة خشب جافة أو بأداة بلاستيكية؛ أما في حالة الجهد العالي فابقَ بعيدًا واتصل بالرقم 115","يجب نقل كل من تعرّض للصعق الكهربائي إلى المستشفى — اتصل بالرقم 122؛ وإذا لم يكن يتنفس، فابدأ CPR"]}],media:[{kind:"video",src:"media/videos/gov_cpr.mp4",title:"CPR والإسعافات الأولية",description:"تدريب الموظفين على CPR"}],quiz:[{question:"في CPR، كم ضغطة صدرية يجب إجراؤها في الدقيقة؟",options:[{text:"50-70",correct:!1},{text:"80-90",correct:!1},{text:"100-120",correct:!0},{text:"150+",correct:!1}],explanation:"يجب أن يكون المعدل 100-120 ضغطة في الدقيقة (AHA 2025)."},{question:"إذا كان هناك جسم حاد داخل الجرح، فماذا تفعل؟",options:[{text:"أنزعه",correct:!1},{text:"أتركه في مكانه وأتصل بالرقم 122",correct:!0},{text:"أُبعد يدي ولا أفعل شيئًا",correct:!1},{text:"أغسله بالماء",correct:!1}],explanation:"نزع الجسم يزيد النزيف؛ ثبّته من حوله واتصل بالرقم 122."},{question:"إذا تعرّض شخص للصعق الكهربائي، فما أول ما يجب فعله؟",options:[{text:"أمسك بيده",correct:!1},{text:"أُجري CPR",correct:!1},{text:"أفصل الكهرباء",correct:!0},{text:"أسكب عليه الماء",correct:!1}],explanation:"يجب فصل الكهرباء أولًا، لكي لا تصبح أنت نفسك ضحية."}]},{id:17,code:"GOV-117",icon:"FlameKindling",accent:"#dc2626",title:"تصنيف أنواع الحرائق",subtitle:"Fire Classification — NFPA 10 / BS EN 2",summary:"التصنيف الدولي لأنواع الحرائق واختيار مطفأة الحريق المناسبة",blocks:[{body:"يُعدّ تصنيف الحرائق أساس عمل الدفاع المدني. والنظامان الرئيسيان هما NFPA 10 (المعيار الأمريكي) وEN 2 (المعيار الأوروبي)، ويجب دائمًا تحديد النظام المقصود. تُكتب الفئات هنا بأحرف NFPA 10 كمرجع للمشروع، ولم يُؤكَّد بعدُ النظام الرسمي في دهوك. ما يقابلها في EN 2: NFPA A = EN A؛ NFPA B (السوائل) = EN B؛ NFPA B (الغازات) = EN C؛ NFPA C (المعدات الكهربائية الموصولة بالتيار) لا فئة لها في EN؛ NFPA D = EN D؛ NFPA K = EN F. فاختيار مطفأة حريق خاطئة قد يؤدي إلى تفاقم الحريق أو إلى وقوع إصابات. ويشرح هذا الدرس كل فئة وفقًا للمعايير الدولية."},{heading:"1. الفئة A — المواد الصلبة (Solid Combustibles)",body:"المواد الصلبة العضوية التي تخلّف رمادًا:",points:["المواد القابلة للاحتراق: الخشب، والورق، والقماش، والبلاستيك، والمطاط، والنفايات","درجة الاشتعال الذاتي: للورق نحو 218-246°C","الخصائص: تخلّف رمادًا وجمرًا، وقد تبقى النار مشتعلة في عمق المادة","مطفآت الحريق: الماء، والمسحوق ABC، والرغوة — اقرأ الملصق (Label) ورموز الفئات (اللون ليس فئة الحريق)","في الدوائر: معظم المواد القابلة للاحتراق هي الورق والملفات وأثاث الغرف","المعايير: NFPA 10، EN 2","التدريب: لا تستخدم المطفأة إلا إذا تحقّق كل ما يلي: الحريق صغير وفي بدايته، والمطفأة مناسبة، وطريق الخروج خلفك، وتمّ إطلاق الإنذار والاتصال بالرقم 115، وأنت مدرَّب، ولا يوجد دخان أو حرارة يمنعان خروجك. ثم طريقة PASS: ابدأ من المسافة المحددة على ملصق المطفأة، ووجِّه فوهة الخرطوم نحو قاعدة النار؛ وإذا لم تنطفئ النار فورًا، فاخرج وأغلق الباب"]},{heading:"2. الفئة B — السوائل القابلة للاشتعال (Flammable Liquids)",body:"السوائل التي تُطلق أبخرة قابلة للاشتعال في درجات الحرارة العادية (وفي NFPA تشمل أيضًا الغازات القابلة للاشتعال):",points:["المواد القابلة للاحتراق: البنزين، وزيت الغاز (Diesel)، والنفط الأبيض، والكحول، والتنر، والدهانات","نقطة الوميض (Flash Point)، بحسب نوع الوقود: للبنزين نحو −43°C، ولزيت الغاز نحو 52-96°C","الخصائص: الذي يحترق هو بخار السائل، لا السائل نفسه","مطفآت الحريق للسوائل: الرغوة أو CO₂ أو المسحوق ABC؛ وللكحول والمذيبات القطبية الأخرى (Polar Solvents): CO₂ أو المسحوق ABC أو الرغوة المقاومة للكحول (AR Foam)، لأن الرغوة العادية تنهار عليها. حريق الغاز (غاز LPG أو الغاز الطبيعي): الأولوية لإيقاف تدفق الغاز؛ يُغلق شخصٌ مؤهَّل صمامَ الغاز فقط إذا كان الوصول إليه آمنًا. لا تُطفئ لهب الغاز إذا لم يمكن إيقاف الغاز بأمان، فالغاز غير المحترق يتجمّع وقد ينفجر. وإذا لم يكن ذلك آمنًا، فأخلِ الجميع، وأطلق الإنذار، واتصل بالرقم 115. والرغوة ليست الخيار العام لحرائق الغاز","لا ترشّ الماء بالخرطوم على السائل المشتعل: فهو يُطاير السائل المشتعل وينشره (Slop-over / Boil-over). أما BLEVE فأمر مختلف: وهو انفجار وعاء مضغوط بعد تعرّضه للحرارة، وقد يساعد تبريد الوعاء بالماء من مسافة بعيدة على منعه؛ وهذه مهمة فريق 115، ويُخلي جميعُ الآخرين المكان","في الدوائر: مخازن وقود المولدات ومركبات الخدمة","المعيار: NFPA 30 (Flammable and Combustible Liquids Code)","الأسلوب: قطع الأكسجين (الخنق / Smothering)، لا التبريد وحده"]},{heading:"3. الفئة C في NFPA — الأجهزة الكهربائية الموصولة بالتيار (Energized Electrical)",body:"الحرائق في الأجهزة الكهربائية أثناء سريان التيار فيها:",points:["المواد القابلة للاحتراق: الحواسيب، والخوادم، والمقابس، واللوحات الكهربائية","حرارة القوس الكهربائي (Arc Flash): تصل إلى نحو 19400°C (35000°F) — أي أشد حرارة من سطح الشمس بنحو 4 أضعاف (OSHA)","مطفآت الحريق: CO₂، والمسحوق ABC، والعوامل النظيفة (Clean Agent) مثل FK-5-1-12","لا تستخدم الماء أو الرغوة على الأجهزة الكهربائية الموصولة بالتيار إلا إذا أظهر الملصق تصنيف الفئة C أو علامة اختبار كهربائي (كبعض مطفآت رذاذ الماء Water Mist) — بسبب خطر الصعق الكهربائي القاتل","أولًا: إن كان الوصول إلى اللوحة آمنًا دون المرور بجانب النار، فافصل الكهرباء منها؛ ثم أطفئ النار وفقًا للمادة المحترقة","المعيار: NFPA 70E (Electrical Safety in the Workplace)","في غرف تقنية المعلومات والاتصالات (ICT): العوامل النظيفة أفضل — فهي لا تُلحق ضررًا بالأجهزة الثمينة","ملاحظة: في EN 2 تمثل الفئة C الغازات لا الكهرباء؛ ففي أوروبا لا تُعدّ الحرائق الكهربائية فئة مستقلة، أما الفئة E (الكهرباء) فتُستخدم في أستراليا فقط"]},{heading:"4. الفئة D — المعادن القابلة للاحتراق (Combustible Metals)",body:"المعادن القابلة للاحتراق — من أخطر الأنواع:",points:["المواد القابلة للاحتراق: المغنيسيوم، والتيتانيوم، والصوديوم، والبوتاسيوم، والليثيوم المعدني","الحرارة: يحترق المغنيسيوم بدرجة حرارة تقارب 3100°C (5610°F)","لا تستخدم الماء أبدًا! فالماء + المغنيسيوم = هيدروجين وانفجار","لا تستخدم CO₂ أبدًا! فالمغنيسيوم يحترق حتى في CO₂ ويزداد الحريق","فقط: مطفأة أو مادة يذكر ملصقها هذا المعدن (مساحيق الفئة D مثل كلوريد الصوديوم أو الغرافيت)، فالمادة تختلف من معدن لآخر (فالليثيوم مثلًا يحتاج مادة مخصّصة لليثيوم). ولا تستخدم المسحوق العادي أو الرغوة أبدًا. ولا يُستخدم الرمل الجاف إلا إذا نصّت عليه خطة الحريق في الموقع أو صحيفة SDS للمعدن وكان جافًا تمامًا","في الدوائر: المختبرات الكيميائية وأماكن تشغيل المعادن. أما بطاريات الليثيوم أيون العادية فلا تحتوي على الليثيوم المعدني، ويُوصى بتبريدها بالماء","المعيار: NFPA 484 (Combustible Metals)","اتصل فورًا بالرقم 115 — إذ يلزم فريق متخصص"]},{heading:"5. الفئة F (EN 2) / الفئة K (NFPA) — زيوت الطبخ (Cooking Oils)",body:"زيوت الطبخ ودهونه — من أكثر حرائق المطابخ شيوعًا:",points:["المواد القابلة للاحتراق: زيوت الطبخ (النباتية والحيوانية) والدهون","درجة الاشتعال الذاتي: أعلى من 340°C عمومًا، بحسب نوع الزيت","المطفأة: المادة الكيميائية الرطبة (Wet Chemical) — أملاح البوتاسيوم؛ وهي مصنوعة لزيوت الطبخ ودهونه، وكثير منها مصنَّف للفئة A أيضًا، لذا اقرأ الملصق واستخدمها وفقه (وفي بريطانيا تحمل شريطًا أصفر وفق BS 7863)","لا تستخدم الماء أبدًا! فالماء يتحول سريعًا إلى بخار داخل الزيت الساخن ويقذف الزيت المشتعل بقوة (كرة نارية)","المسحوق ABC غير مناسب لزيوت الطبخ — فقد يعود الحريق إلى الاشتعال","الأسلوب: إذا كان الحريق صغيرًا، فأوقف مصدر الحرارة وضع غطاءً أو بطانية حريق (Fire Blanket) فوقه ولا ترفعها","في كافتيريا الدائرة: مطفأة Wet Chemical قرب مكان إعداد الطعام (NFPA 10: على مسافة لا تزيد على 9 أمتار)","المعايير: BS EN 3-7، NFPA 10، NFPA 17A (Wet Chemical Systems)"]},{heading:"6. اختيار مطفأة الحريق المناسبة — مصفوفة القرار",body:"الأساس: 1) المادة المحترقة، 2) حجم الحريق، 3) المكان:",points:["المصفوفة: A: الماء أو ABC | B السوائل: الرغوة أو CO₂ أو ABC (المذيبات القطبية: رغوة AR أو CO₂ أو ABC) | B الغاز: أوقف الغاز أولًا إن كان ذلك آمنًا، ولا تُطفئ أبدًا لهب غاز لا تستطيع إيقافه | C: CO₂ أو Clean Agent أو المسحوق ABC (المسحوق يُتلف الأجهزة الإلكترونية) | D: مطفأة D يذكر ملصقها هذا المعدن | F/K: Wet Chemical","الحجم: لا تستخدم مطفأة الحريق إلا لحريق صغير في بدايته؛ ولا تستخدمها إذا كانت النار أكبر من سلة مهملات، أو كانت تنتشر، أو كان الدخان يزداد: اخرج واتصل بالرقم 115","المكان: غرف ICT: Clean Agent أو CO₂ | مخازن الورق: الماء أو ABC | الكافتيريا: Wet Chemical","للدائرة العادية: ABC وCO₂، وWet Chemical في المطبخ","مدة التشغيل: تفرغ المطفآت الصغيرة بسرعة، غالبًا خلال ثوانٍ قليلة، ومدة التفريغ الدقيقة مكتوبة على الملصق — فكن ضمن المدى المحدد على الملصق، وطريق الخروج خلفك، قبل البدء","الفحص والخدمة (NFPA 10 وOSHA؛ ولم تُؤكَّد بعدُ القواعد في دهوك): فحص بصري شهريًا؛ فحص وصيانة سنويًا على يد فني مختص؛ إعادة التعبئة بعد أي استخدام؛ مطفآت المسحوق الجاف ذات الضغط المخزَّن: تفريغ وفحص داخلي كل 6 سنوات؛ اختبار الضغط (Hydrostatic): كل 5 سنوات لمطفآت الماء والرغوة وCO₂ وWet Chemical والمسحوق الجاف ذات الجسم من الفولاذ المقاوم للصدأ (Stainless Steel)، وكل 12 سنة لمطفآت المسحوق الجاف ذات الضغط المخزَّن والجسم من الفولاذ الطري أو النحاس الأصفر الملحوم أو الألمنيوم"]},{heading:"7. مراحل تطور الحريق (Stages of Fire)",body:"يمر كل حريق بـ4 مراحل:",points:["1. البداية (Incipient): دخان قليل ونار صغيرة","2. النمو (Growth): ترتفع الحرارة وتنتشر النار","3. التطور الكامل (Fully Developed): تحترق جميع محتويات الغرفة وقد تتجاوز الحرارة 1000°C","4. الخمود (Decay): يقل الوقود، لكن خطر Backdraft قائم","Flashover بين المرحلتين 2 و3: عندما تصل حرارة طبقة الغازات العليا إلى نحو 500-600°C، تشتعل جميع محتويات الغرفة بسرعة","Backdraft: فتح باب غرفة فيها نار ونقص في الأكسجين يُدخل الأكسجين إليها فيحدث انفجار ناري","استجابة الموظف: لا يكون إطفاء الحريق آمنًا إلا في المرحلة 1 (Incipient)"]}],media:[{kind:"video",src:"media/videos/gov_fire_classes.mp4",title:"تصنيف أنواع الحرائق",description:"عرض فئات الحرائق وفقًا لـNFPA وEN 2"},{kind:"image",src:"media/images/gov_fire_decision.png",title:"مصفوفة القرار (Decision Matrix)",description:"اختيار مطفأة الحريق المناسبة"}],quiz:[{question:"بأي مطفأة يُطفأ حريق الحاسوب (الفئة C في NFPA)؟",options:[{text:"الماء",correct:!1},{text:"CO₂ أو Clean Agent",correct:!0},{text:"الرغوة",correct:!1},{text:"مطفأة D",correct:!1}],explanation:"CO₂ أو Clean Agent — فهما لا يتركان بقايا. ويصلح المسحوق ABC أيضًا لكنه يُتلف الأجهزة الإلكترونية. أما الماء والرغوة العاديان فيوصلان الكهرباء وقد يسببان الصعق."},{question:"ما الفئة D؟",options:[{text:"السوائل",correct:!1},{text:"الخشب والورق",correct:!1},{text:"المعادن القابلة للاحتراق",correct:!0},{text:"الغازات",correct:!1}],explanation:"الفئة D = المعادن القابلة للاحتراق (المغنيسيوم، والتيتانيوم...). ولا تُستخدم لها إلا مطفأة أو مادة يذكر ملصقها هذا المعدن؛ ولا يُستخدم الرمل الجاف إلا إذا نصّت عليه خطة الحريق في الموقع أو صحيفة SDS للمعدن وكان جافًا تمامًا."},{question:"لماذا لا يجوز استخدام الماء على حريق زيت الطبخ؟",options:[{text:"لأنه لا يُجدي",correct:!1},{text:"لأن الماء يتحول إلى بخار ويقذف الزيت المشتعل بقوة",correct:!0},{text:"لأنه ثقيل جدًا",correct:!1},{text:"لأن الزيت لا يشتعل أبدًا",correct:!1}],explanation:"الزيت شديد السخونة يحوّل الماء سريعًا إلى بخار؛ والبخار يقذف الزيت المشتعل ويُحدث كرة نارية."},{question:"ما المعيار NFPA 10؟",options:[{text:"تصنيف الموظفين",correct:!1},{text:"مطفآت الحريق اليدوية (Portable Fire Extinguishers)",correct:!0},{text:"أنظمة رشاشات المياه (Sprinkler)",correct:!1},{text:"حماية البيانات",correct:!1}],explanation:"NFPA 10 هو المعيار الأمريكي لمطفآت الحريق اليدوية: اختيارها، وتركيبها، وفحصها، وصيانتها."},{question:"ما مرحلة الحريق الوحيدة التي يستطيع فيها الموظف إطفاء الحريق بأمان؟",options:[{text:"Decay",correct:!1},{text:"Fully Developed",correct:!1},{text:"Incipient",correct:!0},{text:"Flashover",correct:!1}],explanation:"لا يكون إطفاء الحريق من قِبل الموظف آمنًا إلا في المرحلة الأولى (Incipient)."},{question:"عند أي درجة حرارة تقريبًا لطبقة الغازات العليا يحدث Flashover عمومًا؟",options:[{text:"200°C",correct:!1},{text:"400°C",correct:!1},{text:"نحو 500-600°C",correct:!0},{text:"900°C",correct:!1}],explanation:"يحدث Flashover عندما تصل حرارة طبقة الغازات العليا إلى نحو 500-600°C — فتشتعل جميع محتويات الغرفة بسرعة."}]},{id:18,code:"GOV-118",icon:"FireExtinguisher",accent:"#ea580c",title:"مطفآت الحريق — أنواعها واختيارها",subtitle:"Fire Extinguisher Types — NFPA 10 + BS EN 3",summary:"الأنواع الستة الرئيسية لمطفآت الحريق اليدوية وفقًا للمعايير الدولية واختيارها للدوائر",blocks:[{body:"يجب اختيار مطفأة الحريق في الدوائر وفقًا لنوع الحريق المحتمل. ففي معظم الدوائر، تُشكّل مطفآت المسحوق ABC ومطفآت CO₂ معًا الأساس، مع مطفأة Wet Chemical في المطبخ. ويشرح هذا الدرس الأنواع الستة الرئيسية، وألوانها، وأحجامها، وطريقة PASS، وجدول الفحص. تُكتب الفئات هنا بأحرف NFPA 10 كمرجع للمشروع، ولم يُؤكَّد بعدُ النظام الرسمي في دهوك. ما يقابلها في EN 2: NFPA A = EN A؛ NFPA B (السوائل) = EN B؛ NFPA B (الغازات) = EN C؛ NFPA C (المعدات الكهربائية الموصولة بالتيار) لا فئة لها في EN؛ NFPA D = EN D؛ NFPA K = EN F. اللون ليس فئة الحريق: الألوان أدناه هي الممارسة البريطانية (جسم أحمر وفق BS EN 3 مع شريط ملوّن وفق BS 7863)، ولم تُؤكَّد بعدُ الألوان المتّبعة في دهوك، لذا اقرأ الملصق (Label) ورموز الفئات دائمًا."},{heading:"1. مطفأة الماء — Water (الفئة A)",body:"أكثر المطفآت شيوعًا للفئة A — المواد الصلبة:",points:["اللون في بريطانيا (BS EN 3): أحمر بالكامل بلا شريط","الفئة: A فقط (الخشب، والورق، والقماش، والبلاستيك)","طريقة العمل: تبرّد النار وتخفض الحرارة","الأحجام الشائعة: 6 و9 لترات","المسافة: ابدأ من المسافة المحددة على ملصق المطفأة، وطريق الخروج خلفك، ولا تقترب إلا كلما صغرت النار","لا تستخدمها أبدًا للكهرباء (الصعق) ولا للسوائل ولا لزيوت الطبخ (فهي تنشر النار)","في الدائرة: الممرات وغرف الأرشيف","سعرها منخفض، لكنها مناسبة للفئة A فقط","الفحص: فحص بصري شهري (مقياس الضغط إن وُجد، ومسمار الأمان، والختم) وفحص وصيانة كل سنة من قِبل شخص مختص"]},{heading:"2. مطفأة الرغوة — Foam (الفئتان A وB)",body:"رغوة AFFF (Aqueous Film-Forming Foam):",points:["اللون في بريطانيا (BS EN 3 / BS 7863): أحمر مع شريط كريمي","الفئة: A وB (السوائل القابلة للاشتعال) — وليست للكحول والمذيبات القطبية الأخرى (Polar Solvents) إلا إذا كانت رغوة مقاومة للكحول (AR Foam)، وليست الخيار العام لحرائق الغاز","طريقة العمل: تُكوّن الرغوة طبقة فوق السائل، فتقطع الأكسجين وتبرّد","الأحجام الشائعة: 6 و9 لترات","المسافة: ابدأ من المسافة المحددة على الملصق، ولا تقترب إلا كلما صغرت النار","مناسبة لـ: مخازن الوقود وأماكن المولدات","لا تستخدمها للأجهزة الكهربائية الموصولة بالتيار — فهي توصل الكهرباء كالماء","في الدائرة: موقف السيارات ومخزن زيت الغاز","تحتوي AFFF على مواد PFAS الضارة بالبيئة والصحة؛ والرغوة الخالية من الفلور (Fluorine-Free Foam) هي البديل الحديث"]},{heading:"3. مطفأة CO₂ — Carbon Dioxide (الفئة B والحرائق الكهربائية)",body:"الأفضل للأجهزة الكهربائية والسوائل:",points:["اللون في بريطانيا (BS EN 3 / BS 7863): أحمر مع شريط أسود","الفئة: B والأجهزة الكهربائية الموصولة بالتيار (الفئتان B وC في NFPA؛ وفي EN 2 تعني C الغاز، وCO₂ غير مصنَّفة لحرائق الغاز)","طريقة العمل: يُزيح غاز CO₂ الأكسجين من حول النار (الخنق)","الأحجام الشائعة: 2 و5 كغ","المسافة: مدى CO₂ قصير؛ ابدأ من المسافة المحددة على الملصق، ولا تقترب إلا كلما صغرت النار","مناسبة لـ: غرف ICT، واللوحات الكهربائية، وغرفة الخوادم (Server Room)","لا تترك أي بقايا ولا تُلحق ضررًا بالأجهزة الثمينة؛ لكنها غير فعّالة في حرائق الفئة A العميقة","الخطر: تُخفض الأكسجين في الغرف المغلقة — فأخلِ الغرفة وجدّد هواءها بعد الاستخدام","يصبح البوق باردًا جدًا (نحو −78°C) — لا تلمس البوق، وأمسك المقبض فقط","في الدائرة: قسم ICT، وغرفة الخوادم، وقرب اللوحات الكهربائية"]},{heading:"4. مطفأة المسحوق الجاف ABC — Dry Chemical Powder",body:"أكثر المطفآت شيوعًا — للفئات A وB وC، وليست للفئتين D وK/F:",points:["اللون في بريطانيا (BS EN 3 / BS 7863): أحمر مع شريط أزرق","الفئة: A وB وC — وليست D (المعادن) ولا K/F (زيوت الطبخ)","المادة: فوسفات الأمونيوم الأحادي (Monoammonium Phosphate)","طريقة العمل: يوقف المسحوق التفاعل الكيميائي للنار","الأحجام الشائعة: 1 و2 و6 و9 كغ","المسافة: ابدأ من المسافة المحددة على الملصق، ولا تقترب إلا كلما صغرت النار","مناسبة لـ: الممرات والمرائب والمخازن — وليست لزيوت الطبخ","ينتشر المسحوق في الغرفة، ويحجب الرؤية، ويصعب تنظيفه","يُلحق المسحوق ضررًا بالأجهزة الإلكترونية — ولذلك فإن CO₂ أفضل للحواسيب وأجهزة ICT","في الدائرة: الممرات والمرآب وقرب المخارج","سعرها منخفض، وتُركَّب عادةً في الدوائر"]},{heading:"5. مطفأة المادة الكيميائية الرطبة — Wet Chemical (الفئة F/K) — المطبخ",body:"مخصصة لزيوت المطبخ ودهونه الساخنة:",points:["اللون في بريطانيا (BS EN 3 / BS 7863): أحمر مع شريط أصفر","الفئة: K (NFPA) / F (EN 2) — زيوت الطبخ","المادة: أملاح البوتاسيوم (Potassium Acetate أو Potassium Citrate)","طريقة العمل: تحوّل الزيت إلى طبقة شبيهة بالصابون (Saponification) تبرّد الزيت وتقطع الأكسجين","الأحجام الشائعة: 2 و6 لترات","استخدمها كما يبيّن الملصق: رُشَّها ببطء وبالأنبوب الطويل فوق الزيت لكي لا يتطاير","مصنوعة لزيوت المطبخ ودهونه (NFPA K / EN F)؛ وكثير منها مصنَّف للفئة A أيضًا، لذا اقرأ الملصق. وليست لزيت الغاز والنفط (الفئة B)","لا تصبّ الماء أبدًا على الزيت الساخن — فالماء يتحول إلى بخار ويقذف الزيت المشتعل!","في الدائرة: الكافتيريا والمطبخ","قبل الاستخدام، إن كان ذلك آمنًا، افصل الغاز أو الكهرباء عن جهاز الطهي"]},{heading:"6. العوامل النظيفة — Clean Agent (FK-5-1-12 / HFC-227ea)",body:"لأجهزة ICT والأجهزة الثمينة:",points:["اللون: جسم أحمر مكتوب عليه اسم المادة (وفي بعض الدول شريط أخضر)","الفئة: تختلف بحسب الطراز؛ اقرأ الملصق","المادة: FK-5-1-12 (الاسم التجاري Novec 1230) أو HFC-227ea","طريقة العمل: غاز نظيف — لا يترك أي بقايا ولا يُلحق ضررًا بالأجهزة","تُفرَّغ الأنظمة الثابتة للعوامل النظيفة (NFPA 2001)، وهي ليست مطفآت يدوية، خلال 10 ثوانٍ أو أقل","مناسبة لـ: غرفة الخوادم (Server Room)، ومركز البيانات (Data Center)، والأرشيف","مطفأة العوامل النظيفة اليدوية: تصنيف الفئات والحد الأدنى لحجم الغرفة مكتوبان على الملصق؛ وغادر الغرفة بعد الاستخدام. الأنظمة الثابتة: المادة آمنة للإنسان بتراكيز التصميم، لكن يجب إخلاء الغرفة بسبب الدخان والمواد الناتجة عن الحريق","لا تضر بطبقة الأوزون، وقد حلّت محل Halon 1301","مرتفعة الثمن؛ وفي غرف الخوادم تُركَّب غالبًا بوصفها نظامًا ثابتًا للغمر الكلي للغرفة (Total Flooding)، وهو منفصل عن المطفآت اليدوية","في الدائرة: في الأماكن الحساسة فقط — غرفة الخوادم ومركز عمليات الطوارئ (EOC)","المعيار: NFPA 2001 (Clean Agent Fire Extinguishing Systems)"]},{heading:"7. PASS — طريقة الاستخدام",body:`قبل استخدام المطفأة (يجب أن تكون كل الإجابات «نعم»):
• الحريق صغير وفي بدايته، مثل حريق في سلة مهملات أو مقلاة.
• المطفأة مناسبة لهذا النوع من الحريق.
• طريق الخروج خلفك، والنار ليست بينك وبين المخرج.
• تمّ إطلاق الإنذار: نُبِّه الآخرون واتُّصل بالرقم 115.
• أنت مدرَّب على استخدام المطفأة.
• لا يوجد دخان أو حرارة يمنعان خروجك.
• إذا لم تنطفئ النار فورًا، فتوقّف واخرج وأغلق الباب خلفك.

طريقة PASS هي الطريقة العامة لمعظم مطفآت الحريق اليدوية. أما مطفآت الفئة D والمادة الكيميائية الرطبة (Wet Chemical) والعوامل النظيفة (Clean Agent) والمطفآت ذات العجلات فتُستخدم وفق الملصق وتعليمات الشركة المصنّعة. خطوة بخطوة:`,points:["P = Pull (اسحب): اسحب مسمار الأمان واكسر الختم","A = Aim (وجِّه): وجِّه فوهة الخرطوم نحو قاعدة النار لا أعلاها — ابدأ من المسافة المحددة على ملصق المطفأة، ولا تقترب إلا كلما صغرت النار","S = Squeeze (اضغط): اضغط المقبض بقوة وباستمرار","S = Sweep (حرِّك): من جانب إلى آخر، ببطء، حتى تنطفئ النار","تفرغ المطفآت الصغيرة بسرعة، غالبًا خلال ثوانٍ قليلة؛ ومدة التفريغ الدقيقة مكتوبة على الملصق — فكن مستعدًا","موضع الوقوف: يجب أن يكون طريق الخروج (الباب) خلفك","بعد الإطفاء راقب المكان؛ وإذا عاودت النار الاشتعال، فكرّر PASS أو اخرج","إذا لم تنطفئ النار فورًا أو فرغت المطفأة: اخرج فورًا، وأغلق الباب خلفك، وتأكد من الاتصال بالرقم 115"]},{heading:"8. الاختيار المناسب للدوائر",body:"خطة مطفآت الحريق في الدائرة:",points:["مثال لدائرة: ABC في الممرات، وCO₂ قرب الأجهزة الكهربائية وأجهزة ICT، وWet Chemical في المطبخ (إن وُجد)","وفق NFPA 10، في منطقة الخطر المنخفض (Light Hazard) تغطي كل وحدة A (A Unit) مساحة تصل إلى 3000 قدم مربع (نحو 279 م²)، لذا تغطي المطفأة بتصنيف 2-A مساحة تصل إلى نحو 557 م² (6000 قدم مربع)؛ ولا يجوز أن تغطي مطفأة واحدة أكثر من نحو 1045 م² (11250 قدمًا مربعًا)، ويجب ألّا يضطر أحد إلى السير أكثر من 23 م (75 قدمًا) للوصول إلى مطفأة. ويوصي الكود البريطاني BS 5306-8 بمطفأتين (2) على الأقل في كل طابق (باستثناء الطوابق الصغيرة جدًا). أما المتطلب الخاص بدوائر دهوك فتضعه مديرية الدفاع المدني، ولم يُؤكَّد بعدُ","مسافة الوصول (Travel Distance): لا تزيد على 23 مترًا للفئة A، و9 أو 15 مترًا للفئة B (بحسب تصنيف المطفأة)، و9 أمتار للفئة K (NFPA 10)","على الجدار وقرب الأبواب؛ ولا يزيد ارتفاع أعلى المطفأة على 1.5 متر عن الأرض (للمطفآت حتى 18 كغ — NFPA 10)","ضع علامة مطفأة الحريق (ISO 7010 F001) في مكان مرتفع لكي تُرى من بعيد","الفحص البصري (شهريًا، من قِبل موظف معيَّن): في مكانها، ظاهرة ويسهل الوصول إليها؛ مسمار الأمان والختم سليمان؛ الملصق مقروء ومتجه إلى الخارج؛ لا ضرر ولا صدأ ولا تسرّب؛ الخرطوم والفوهة غير مسدودين؛ ومؤشر مقياس الضغط في المنطقة الخضراء إن وُجد. مطفآت CO₂ لا مقياس لها: ارفعها لتتأكد من أنها ممتلئة","الفحص والصيانة (سنويًا، على يد فني مختص من شركة معتمدة)","إعادة التعبئة (Recharge): بعد أي استخدام ولو كان قصيرًا، على يد فني مختص","صيانة السنوات الست: تُفرَّغ مطفآت المسحوق الجاف (ABC) ذات الضغط المخزَّن (Stored Pressure) التي تحتاج إلى اختبار ضغط كل 12 سنة، ويُفحص داخلها كل 6 سنوات (NFPA 10) — وهذا لا يعني استبدال المطفأة","اختبار ضغط جسم المطفأة (Hydrostatic Test) بحسب النوع: كل 5 سنوات لمطفآت الماء والرغوة (AFFF) وCO₂ وWet Chemical والمسحوق الجاف ذات الجسم من الفولاذ المقاوم للصدأ (Stainless Steel)؛ وكل 12 سنة لمطفآت المسحوق الجاف (ABC) ذات الضغط المخزَّن والجسم من الفولاذ الطري (Mild Steel) أو النحاس الأصفر الملحوم (Brazed Brass) أو الألمنيوم. ولم تُؤكَّد بعدُ القواعد في دهوك","السحب من الخدمة: تُسحب المطفأة من الخدمة إذا لم تنجح في الفحص أو الاختبار، أو تضرّرت، أو أصبحت قديمة الطراز (Obsolete) أو استدعتها الشركة المصنّعة (Recall)، أو لم يعد ملصقها مقروءًا، أو كانت غير قابلة لإعادة التعبئة (Non-rechargeable) وتجاوزت مدة الخدمة المكتوبة على ملصقها"]}],media:[{kind:"video",src:"media/videos/gov_ext_pass.mp4",title:"طريقة PASS (PASS Technique)",description:"تجربة طريقة PASS"},{kind:"image",src:"media/images/gov_ext_chart.png",title:"جدول اختيار مطفآت الحريق (Extinguisher Selection Chart)",description:"الاختيار وفقًا لفئة الحريق"}],quiz:[{question:"لأي الفئات تصلح مطفأة ABC؟",options:[{text:"A فقط",correct:!1},{text:"A + B + C",correct:!0},{text:"B + C فقط",correct:!1},{text:"D + K",correct:!1}],explanation:"مطفأة ABC للفئات A وB وC (فوسفات الأمونيوم) — وليست للفئة D (المعادن) ولا للفئة K/F (زيوت الطبخ)."},{question:"أي مطفأة حريق مناسبة لغرفة الخوادم (Server Room)؟",options:[{text:"المسحوق ABC",correct:!1},{text:"الماء",correct:!1},{text:"Clean Agent (FK-5-1-12)",correct:!0},{text:"الرغوة",correct:!1}],explanation:"لا تترك العوامل النظيفة (Clean Agent) أي بقايا ولا تُلحق ضررًا بالأجهزة."},{question:"ماذا يعني الحرف P في PASS؟",options:[{text:"Push",correct:!1},{text:"Pull",correct:!0},{text:"Point",correct:!1},{text:"Press",correct:!1}],explanation:"P = Pull (اسحب مسمار الأمان)."},{question:"وفقًا لـNFPA 10، ما الحد الأقصى لمسافة الوصول (Travel Distance) إلى مطفأة الفئة A؟",options:[{text:"10 أمتار",correct:!1},{text:"23 مترًا",correct:!0},{text:"50 مترًا",correct:!1},{text:"100 متر",correct:!1}],explanation:"NFPA 10: حتى 23 مترًا (75 قدمًا) للفئة A؛ و9 أو 15 مترًا للفئة B بحسب تصنيف المطفأة."},{question:"كم تبلغ درجة حرارة CO₂ تقريبًا عند خروجه من المطفأة؟",options:[{text:"0°C",correct:!1},{text:"−78°C",correct:!0},{text:"−30°C",correct:!1},{text:"20°C",correct:!1}],explanation:"يخرج CO₂ بدرجة حرارة تقارب −78°C — فلا تلمس البوق، لكي لا تُصاب يدك بقضمة الصقيع (Frostbite)."},{question:"ما خطر رغوة AFFF؟",options:[{text:"لا يوجد خطر",correct:!1},{text:"PFAS — ضرر بيئي",correct:!0},{text:"مرتفعة الثمن جدًا",correct:!1},{text:"باردة جدًا",correct:!1}],explanation:"تحتوي AFFF على مواد مفلورة (PFAS) تشكّل خطرًا على البيئة؛ والرغوة الخالية من الفلور هي البديل الحديث."}]},{id:19,code:"GOV-119",icon:"HeartHandshake",accent:"#db2777",title:"الإسعافات الأولية للموظفين",subtitle:"Workplace First Aid — Primary Check + CPR + AED + Common Emergencies",summary:"برنامج شامل للإسعافات الأولية لموظفي الدوائر",blocks:[{body:"في حالات الطوارئ، تكون الدقائق الأولى بالغة الأهمية: فإذا توقف القلب، يبدأ تلف الدماغ بعد بضع دقائق، وكل دقيقة تأخير في الإنعاش القلبي الرئوي (CPR) وصدمة جهاز إزالة الرجفان الخارجي الآلي (AED) تُقلل فرصة النجاة. ويشرح هذا الدرس الفحص الأولي، وCPR في الدائرة، وجهاز AED، والاختناق، والنزيف، والحروق، وحالات الطوارئ الشائعة الأخرى."},{heading:"1. الفحص الأولي — الخطر، الاستجابة، التنفس",body:"الإجراء الأول عند رؤية شخص ساقط أو فاقد للقوة:",points:["الخطر (Danger): افحص المكان قبل الاقتراب: هل توجد كهرباء أو نار أو غاز أو حركة مرور؟ سلامتك أولًا","الاستجابة (Response): هزّ كتفيه برفق واسأله بصوت عالٍ: «هل أنت بخير؟»","إذا لم يستجب: اطلب المساعدة، واتصل بالرقم 122 (ضع الهاتف على مكبر الصوت)، وأرسل شخصًا لإحضار جهاز AED","التنفس (Breathing): راقب الصدر مدة تصل إلى 10 ثوانٍ لترى هل يرتفع وينخفض بصورة طبيعية أم لا","إذا لم يكن يتنفس أو كان يلهث بأنفاس غير طبيعية فقط (Gasping): فهذا توقف للقلب — ابدأ الضغطات الصدرية فورًا","لا يفحص الأشخاص العاديون (غير الأطباء) النبض (Pulse) — فلا تُضِع الوقت في الفحص","إذا كان يتنفس بصورة طبيعية: ضعه على جنبه في وضعية الإفاقة (Recovery Position)، ولا تعطه شيئًا عن طريق الفم، وراقب تنفسه حتى وصول سيارة الإسعاف"]},{heading:"2. CPR في الدائرة",body:"للموظفين (غير الأطباء):",points:["موضع اليدين: منتصف الصدر (النصف السفلي من عظمة القص)، يد فوق الأخرى","يجب أن تكون الذراعان مستقيمتين وكتفاك فوق الصدر مباشرةً؛ واضغط مستعينًا بثقل وركيك وجسمك","العمق: 5-6 سم لجميع البالغين","المعدل: 100-120 ضغطة في الدقيقة؛ واترك الصدر يعود إلى وضعه بالكامل بعد كل ضغطة","النسبة: 30 ضغطة + نَفَسان (2)؛ وإذا لم تتلقَّ تدريبًا، فاكتفِ بالضغطات الصدرية (Hands-Only CPR)","إذا وُجد شخصان: تبادلا الأدوار كل دقيقتين (5 دورات) لكي لا تضعف قوة الضغطات","لا تتوقف حتى: يصل جهاز AED ويعمل، أو يصل الفريق الطبي، أو يستعيد الشخص وعيه بوضوح","الأخطاء الشائعة: العمق غير الكافي، والمعدل البطيء، والتوقفات الطويلة، وعدم ترك الصدر يعود إلى وضعه"]},{heading:"3. جهاز إزالة الرجفان الخارجي الآلي (AED — Automated External Defibrillator)",body:"يُوصى بتوفيره في كل مبنى حكومي كبير:",points:["الموضع: في ممر عام وظاهر، ليسهل الوصول إليه بسرعة","العلامة: صندوق يحمل علامة AED (ISO 7010 E010) مع إضاءة واضحة","الهدف: أن يصل جهاز AED إلى أي موقع في المبنى خلال نحو 3 دقائق","الخطوات: 1) شغّله، 2) ضع الوسادتين اللاصقتين على الصدر العاري، 3) استمع إلى التعليمات الصوتية، 4) إذا طلب الجهاز الصدمة، فاضغط الزر","قبل الصدمة قل بصوت عالٍ: «ابتعدوا!» — ولا يلمس أحد المصاب","الفحص الشهري: البطارية وتاريخ انتهاء صلاحية الوسادتين","بعد الصدمة: أجرِ CPR فورًا مدة دقيقتين، ثم يُعيد جهاز AED تحليل نظم القلب","بعد الاستخدام: ركّب وسادتين جديدتين وبطارية جديدة ليكون الجهاز جاهزًا للمرة القادمة"]},{heading:"4. الاختناق (Choking)",body:"إذا علق شيء في حلق الشخص:",points:["الفحص: هل يستطيع الكلام أو السعال أو التنفس؟","إذا كان يسعل بقوة: شجّعه على السعال وابقَ بجانبه","إذا لم يستطع الكلام أو السعال أو التنفس: اتصل بالرقم 122 (أو اطلب من شخص آخر الاتصال) وابدأ فورًا","5 ضربات على الظهر: أمِله إلى الأمام واضربه بقوة بأسفل راحة اليد بين لوحي الكتفين","5 ضغطات على البطن (Heimlich): قف خلفه، وضع قبضتك فوق السرة وأسفل عظمة القص بمسافة كافية، وأمسكها باليد الأخرى واضغط بسرعة إلى الداخل وإلى الأعلى","كرّر 5 ضربات على الظهر و5 ضغطات على البطن حتى يخرج الجسم؛ وإذا فقد وعيه، فابدأ CPR","الرضّع دون سنة واحدة: 5 ضربات على الظهر (والرأس أخفض من الصدر) + 5 ضغطات على الصدر بأسفل راحة يد واحدة؛ ولا تُجرِ ضغطات البطن أبدًا","المرأة الحامل أو الشخص الذي لا تحيط يداك ببطنه: ضغطات على الصدر (Chest thrusts) بدلًا من ضغطات البطن"]},{heading:"5. إيقاف النزيف (Stop the Bleed)",body:"الإجراءات الثلاثة الرئيسية في Stop the Bleed:",points:["1. الضغط المباشر: ضع قطعة قماش نظيفة على الجرح واضغط بكلتا يديك بقوة ومن دون توقف","2. حشو الجرح (Wound Packing): في الجروح العميقة (الفخذ، والإبط، والرقبة)، احشُ الجرح بالشاش النظيف واضغط بقوة","3. الرباط الضاغط (Tourniquet): للنزيف الخطير من الذراع أو الساق، وبصورة مبكرة؛ على بُعد 5-7 سم فوق الجرح، لا فوق المفصل","دوِّن وقت وضع الرباط الضاغط ولا ترخِه أو تفكّه أبدًا — فالفريق الطبي وحده هو من يزيله","لا تنزع أبدًا الجسم المنغرس من الجرح (فسيزداد النزيف)","إذا كان هناك جسم منغرس: لُفّ القماش حوله لكي لا يتحرك، واضغط حوله لا عليه","جرح الرأس: اضغط برفق؛ وإذا اشتُبه في كسر الجمجمة، فلا تضغط بقوة","جرح العين: لا تضغط على العين — بل غطِّها برفق بقطعة قماش نظيفة فقط","في النزيف الشديد اتصل فورًا بالرقم 122؛ وإذا تشبّع القماش بالدم فلا تنزعه — بل ضع قطعة أخرى فوقه"]},{heading:"6. الحروق (Burns)",body:"درجات الحروق ونسبة مساحة سطح الجسم المحترقة (TBSA):",points:["الدرجة الأولى (سطحية): احمرار وألم فقط — مثل حروق الشمس","الدرجة الثانية (متوسطة العمق): فقاعات وألم شديد","الدرجة الثالثة (عميقة): يصبح الجلد أبيض أو بنيًا أو أسود؛ وقد لا يوجد ألم لأن الأعصاب احترقت","قاعدة التسعات (Rule of 9s) للبالغين: الرأس 9%، وكل ذراع 9%، وكل ساق 18%، والصدر والبطن 18%، والظهر 18%، والأعضاء التناسلية 1%","برِّد الحرق فورًا بماء بارد جارٍ مدة 20 دقيقة (لا الثلج ولا الماء شديد البرودة)","ثم غطِّه برفق بغلاف الطعام البلاستيكي (Cling Film) أو بقطعة قماش نظيفة غير لاصقة","الحروق الكيميائية: اغسلها بالماء الجاري مدة 20 دقيقة على الأقل، وراجع صحيفة SDS","الحروق الكهربائية: افصل الكهرباء أولًا؛ فهناك جرح دخول وجرح خروج، وقد يكون الضرر الداخلي أكبر","لا تستخدم أبدًا: الثلج أو الزيت أو الكريمات أو معجون الأسنان؛ ولا تفقأ الفقاعات ولا تنزع الملابس الملتصقة","اتصل بالرقم 122 إذا: كان الحرق كبيرًا أو عميقًا، أو في الوجه أو اليدين أو القدمين أو الأعضاء التناسلية، أو كان حرقًا كهربائيًا، أو استنشق المصاب الدخان"]},{heading:"7. حالات طوارئ شائعة أخرى",body:"حالات شائعة في الدوائر:",points:["الإغماء (Fainting): ضعه على ظهره، وإذا لم يكن مصابًا فارفع ساقيه نحو 30 سم، وأدخل هواءً نقيًا إلى الغرفة","طوارئ السكري (Diabetic Emergency): إذا كان واعيًا ويستطيع البلع، فأعطه سكرًا أو مشروبًا محلّى. وإذا كان فاقدًا للوعي: لا تعطه شيئًا عن طريق الفم، وضعه على جنبه واتصل بالرقم 122. ولا يُعطى الغلوكاغون (Glucagon) إلا إذا وصفه الطبيب له وكنت مدرَّبًا عليه","نوبة الهلع (Panic Attack): تحدّث معه بهدوء وساعده على التنفس ببطء؛ ولم يعد التنفس داخل كيس ورقي موصى به","إصابة الرأس: إذا اشتُبه في إصابة العمود الفقري فلا تحرّكه، وراقب وعيه وتنفسه، واتصل بالرقم 122","الكسر (Fracture): ثبّت العضو على وضعه (Splint) ولا تحاول تقويمه، وضع ثلجًا ملفوفًا بقطعة قماش لتخفيف الألم، واتصل بالرقم 122","الصعق الكهربائي: افصل الكهرباء، وأجرِ CPR إذا لم يكن يتنفس؛ ويجب أن يخضع كل المصابين لتخطيط القلب (ECG) في المستشفى","التسمم: 1) ما المادة؟ 2) ما الكمية؟ 3) متى؟ — اتصل بالرقم 122، وخذ عبوة المادة معك، ولا تحثّه على التقيؤ","لدغة الأفعى (Snake Bite): أبقِ الشخص هادئًا ومن دون حركة وثبّت العضو بجبيرة؛ ولا تربط العضو، ولا تجرح مكان اللدغة، ولا تمصّ الدم؛ واتصل فورًا بالرقم 122"]}],media:[{kind:"video",src:"media/videos/gov_cpr_workplace.mp4",title:"CPR في الدائرة (Workplace CPR)",description:"CPR في مكان العمل"},{kind:"video",src:"media/videos/gov_aed_demo.mp4",title:"عرض جهاز AED (AED Demo)",description:"استخدام جهاز AED"}],quiz:[{question:"ما الخطوة الأولى في الفحص الأولي؟",options:[{text:"CPR فورًا",correct:!1},{text:"فحص الخطر (Danger)",correct:!0},{text:"الاتصال بالرقم 122",correct:!1},{text:"AED",correct:!1}],explanation:"قبل أي شيء تأكد من أن المكان آمن لك — فإذا أُصبت، فلن تستطيع تقديم المساعدة."},{question:"في CPR، ما عمق الضغطات للبالغين؟",options:[{text:"2-3 سم",correct:!1},{text:"5-6 سم",correct:!0},{text:"8-10 سم",correct:!1},{text:"لا شيء مما سبق",correct:!1}],explanation:"5-6 سم لجميع البالغين (AHA 2025)."},{question:"إذا أُعطيت صدمة AED خلال الدقائق 3-5 الأولى بعد السقوط، فإلى أي حد قد تصل فرصة النجاة؟",options:[{text:"10%",correct:!1},{text:"حتى 50-70%",correct:!0},{text:"20%",correct:!1},{text:"100%",correct:!1}],explanation:"قد ترفع الصدمة المبكرة خلال 3-5 دقائق نسبة النجاة إلى 50-70%؛ وكل دقيقة تأخير تُقلل الفرصة بنسبة ملحوظة."},{question:"ماذا يُفعل لرضيع دون سنة واحدة يختنق (وهو واعٍ)؟",options:[{text:"ضغطات البطن (Heimlich) فورًا",correct:!1},{text:"5 ضربات على الظهر + 5 ضغطات على الصدر",correct:!0},{text:"تركه فقط",correct:!1},{text:"CPR فورًا",correct:!1}],explanation:"5 ضربات على الظهر و5 ضغطات على الصدر بأسفل راحة يد واحدة — ولا تُجرَ ضغطات البطن للرضّع أبدًا (AHA 2025)."},{question:"بعد وضع الرباط الضاغط (Tourniquet)، ماذا يجب أن تفعل؟",options:[{text:"أرخِه كل 6 ساعات",correct:!1},{text:"دوِّن وقت وضعه ولا ترخِه أبدًا",correct:!0},{text:"أزِله بعد 10 دقائق",correct:!1},{text:"أرخِه كل 20 دقيقة ليصل الدم",correct:!1}],explanation:"دوِّن وقت الوضع (Stop the Bleed). يبقى الرباط الضاغط في مكانه حتى يزيله الفريق الطبي؛ فإرخاؤه يُعيد النزيف."},{question:"بأي ماء يجب تبريد الحرق مدة 20 دقيقة؟",options:[{text:"الماء الساخن",correct:!1},{text:"الماء البارد الجاري، لا الثلج",correct:!0},{text:"الثلج",correct:!1},{text:"الأدوية والمراهم",correct:!1}],explanation:"الماء البارد الجاري — لا الماء الساخن (فهو يُعمّق الحرق) ولا الثلج (فهو يضر الجلد)."}]},{id:20,code:"GOV-120",icon:"Siren",accent:"#2563eb",title:"عمليات الدفاع المدني والتنسيق",subtitle:"CD Operations + ICS + Multi-Agency Response",summary:"دور الدائرة أثناء استجابة الدفاع المدني (115) والتنسيق مع الجهات الأخرى",blocks:[{body:"يجب أن تعرف الدوائر كيف تعمل مع الدفاع المدني (115) في حالات الطوارئ. ويُعدّ المعيار NFPA 1660 (الذي دُمج فيه NFPA 1600) ودورات FEMA ICS-100/200 أسسًا دولية. ووفقًا لنظام ICS، يتولى قائد واحد للحادث (Incident Commander) إصدار الأوامر، وتعمل جميع الفرق الطبية والشرطة وفرق الإطفاء والدوائر تحت هذه القيادة."},{heading:"1. نظام قيادة الحوادث (ICS)",body:"معيار موحَّد لجميع الجهات:",points:["دورتا ICS-100 وICS-200 ضروريتان للموظفين الرئيسيين","قائد الحادث (IC): واحد فقط، ويتحمل المسؤولية العامة عن الحادث","خمسة أقسام: القيادة (Command)، والعمليات (Operations)، والتخطيط (Planning)، والدعم اللوجستي (Logistics)، والمالية والإدارة (Finance/Admin)","نطاق الإشراف (Span of Control): 3-7 أشخاص لكل مشرف (والأمثل 5)","يحصل كل حادث على اسم خاص (التاريخ + المكان + النوع)","اللغة البسيطة (Plain Language): لا تستخدم الرموز والاختصارات الخاصة","خطة عمل الحادث (IAP) لكل فترة عمل (Operational Period)، وتكون عادةً 12 أو 24 ساعة","إذا كانت عدة جهات مسؤولة: القيادة الموحَّدة (Unified Command) — يضع قادة الجهات معًا خطة واحدة"]},{heading:"2. تقرير SALUTE — إبلاغ الدفاع المدني 115",body:"عند الاتصال، اذكر هذه العناصر الستة (6):",points:["S = Size (الحجم): كم شخصًا، وكم مصابًا، وكم مبنى أو معدة","A = Activity (النشاط): ماذا حدث — حريق، انفجار، حادث، تسمم","L = Location (المكان): العنوان الدقيق — الشارع، واسم الدائرة، ومعلم قريب","U = Unit (الجهة): من أنت — اسم الدائرة ودورك","T = Time (الوقت): متى بدأ الحادث وكم مضى من الوقت","E = Equipment (المعدات): ما المعدات المتوفرة لديك وما المطلوب","أكمِل SALUTE كله في أقل من 60 ثانية؛ وإذا كان الوقت ضيقًا، فاذكر المكان قبل كل شيء، ولا تُنهِ المكالمة حتى يطلب منك المشغّل ذلك"]},{heading:"3. الاستجابة متعددة الجهات (Multi-Agency Response)",body:"عند وصول عدة جهات:",points:["115 الدفاع المدني: إطفاء الحرائق، والإنقاذ، والمواد الخطرة (HazMat)","122 الإسعاف: العلاج الطبي والنقل","104 الشرطة: تطويق المحيط وتنظيم حركة المرور","دائرة الكهرباء: قطع التيار الكهربائي","دائرتا الماء والغاز: قطع الماء والغاز في حال وجود تسرّب","وزارة الصحة: تجهيز المستشفيات","هيئة البيئة: انسكاب المواد الكيميائية","مركز عمليات الطوارئ (EOC — Emergency Operations Center) للحوادث الكبرى"]},{heading:"4. دور الدائرة أثناء الطوارئ",body:"ما يجب عليك فعله حتى يصل الدفاع المدني (115):",points:["1. اتصل بالرقم 115 (وبالرقم 122 إذا وُجد مصابون) مستخدمًا تقرير SALUTE","2. فعِّل الإنذار الداخلي (جرس الحريق أو مكبر الصوت)","3. الموظفون في نقطة التجمع — عدّ الأشخاص (Accountability)","4. جهّز مخطط المبنى: المخاطر وصمامات ومفاتيح الكهرباء والغاز والماء","5. ضابط الارتباط (Liaison Officer): شخص واحد فقط يتواصل مع الدفاع المدني 115","6. جهّز صحائف SDS وقوائم الاتصال","7. تنظيم حركة المرور: أبقِ الطريق مفتوحًا لمركبات الطوارئ","8. مسؤول الإعلام العام (PIO): إعلام المواطنين ووسائل الإعلام بصورة منظمة","9. التوثيق: الصور ومقاطع الفيديو وأقوال الشهود","10. تسليم القيادة: عند وصول الدفاع المدني (115)، تُسلَّم القيادة إلى قائد فريق 115"]},{heading:"5. فريق الاستجابة للطوارئ في الدائرة (ERT)",body:"التشكيلة المقترحة:",points:["قائد الحادث (IC): المدير أو معاونه","منسق الإنذار: زر إنذار الحريق والاتصالات","مسؤولو الطوابق (Floor Wardens): اثنان (2) في كل طابق، لمسارات الإخلاء","فريق الإسعافات الأولية: 2-3 موظفين مدرَّبين على CPR وAED","فريق البحث: تفتيش الغرف والتأكد من إخلاء المبنى","فريق مطفآت الحريق: موظفون مدرَّبون على إطفاء الحرائق الصغيرة في مرحلتها الأولى","الاتصالات: الهاتف مع الدفاع المدني 115 والتنسيق الداخلي","التدريب: تدريب أولي وتحديث سنوي"]},{heading:"6. التمارين والاختبار (Drills + Tabletop Exercises)",body:"أنواع التمارين (FEMA HSEEP):",points:["تمرين الإخلاء (Drill): وفقًا لهذا البرنامج، مرة واحدة كل 3 أشهر","التمرين المكتبي (Tabletop Exercise): يناقش المديرون والمسؤولون سيناريو حول الطاولة","التمرين الوظيفي (Functional Exercise): تُختبر الفرق والمهام الرئيسية فقط (الاتصال، والقيادة)","التمرين الشامل (Full-Scale): المبنى بأكمله والجهات الخارجية، مرة واحدة في السنة على الأقل","اكتب تقرير ما بعد التمرين (After-Action Report) في أسرع وقت","الهدف: تحديد ما نجح، وما كان ناقصًا، وما يجب تغييره","التحسين المستمر: أدرِج نتائج AAR في إجراءات العمل القياسية (SOP)"]},{heading:"7. خطة الاتصال (Communication Plan)",body:"من دون اتصال، لا يسير أي عمل على نحو صحيح:",points:["الأساسية: هواتف الدائرة ونظام مكبرات الصوت (PA)","الثانوية: الهواتف المحمولة وأجهزة اللاسلكي ثنائية الاتجاه","الثالثة: إرسال أشخاص سيرًا على الأقدام (Runners)","البديلة: الهاتف الفضائي للحوادث الكبرى","الاختبار: أسبوعيًا للفرق الرئيسية","قائمة الهواتف: جاهزة على مدار الساعة (24/7) ومحدَّثة","للمواطنين: الخط الهاتفي، والموقع الإلكتروني، ووسائل التواصل الاجتماعي — عبر PIO فقط","ملاحظة: في الحوادث الكبرى قد تزدحم شبكة الهاتف المحمول — والرسائل النصية SMS تصل عادةً بصورة أفضل"]},{heading:"8. التقييم بعد الحادث (After-Action Review)",body:"المراجعة بعد الحادث:",points:["التوصية: خلال 72 ساعة بعد كل حادث، والذاكرة لا تزال حاضرة","مشاركة جميع الجهات: IC، والعمليات، والدعم اللوجستي، والجهات الخارجية","4 أسئلة: ما الذي كان مخططًا له؟ ماذا حدث؟ لماذا وُجد الاختلاف؟ ما الذي سنغيّره في المرة القادمة؟","المؤشرات: زمن الاستجابة، وعدد المصابين، والخسائر المادية","التوثيق: تقرير الدروس المستفادة (Lessons Learned)","التحديث: SOP، وخطة عمليات الطوارئ (EOP)، ومواد التدريب","المتابعة: افحص التنفيذ بعد 30 و60 و90 يومًا","المشاركة: شارك النتائج مع الجهات الأخرى"]}],media:[{kind:"video",src:"media/videos/gov_ics_demo.mp4",title:"ICS أثناء العمل (ICS in Action)",description:"ICS في كارثة حقيقية"},{kind:"image",src:"media/images/gov_salute_card.png",title:"بطاقة SALUTE (SALUTE Report Card)",description:"بطاقة تذكير بـSALUTE"}],quiz:[{question:"في ICS، كم قائدًا للحادث (IC) يلزم؟",options:[{text:"3-5",correct:!1},{text:"واحد فقط",correct:!0},{text:"كل موظف",correct:!1},{text:"2-4",correct:!1}],explanation:"في ICS يوجد قائد واحد للحادث. وإذا كانت عدة جهات مسؤولة، تعمل القيادة الموحَّدة (Unified Command) وفق خطة مشتركة واحدة."},{question:"في SALUTE، ماذا يعني الحرف S؟",options:[{text:"Stop",correct:!1},{text:"Size",correct:!0},{text:"Send",correct:!1},{text:"Save",correct:!1}],explanation:"S = Size (حجم الحادث)."},{question:"عند وصول الدفاع المدني (115)، إلى من تنتقل القيادة؟",options:[{text:"يستمر فريق ERT",correct:!1},{text:"قائد فريق 115",correct:!0},{text:"ضابط الارتباط (Liaison)",correct:!1},{text:"الشرطة",correct:!1}],explanation:"تسليم القيادة: عند وصول الدفاع المدني (115)، تُسلَّم القيادة إلى قائد فريق 115 ويساعده فريق ERT."},{question:"ما التمرين المكتبي (Tabletop Exercise)؟",options:[{text:"تمرين إخلاء المبنى بأكمله",correct:!1},{text:"مناقشة سيناريو حول الطاولة مع المسؤولين",correct:!0},{text:"اختبار صفارة الإنذار",correct:!1},{text:"التدريب على استخدام مطفآت الحريق",correct:!1}],explanation:"التمرين المكتبي مناقشة لسيناريو دون تحريك الأشخاص أو المعدات، بهدف اختبار الخطط والمهام (FEMA HSEEP)."},{question:"خلال كم ساعة يُوصى بإجراء التقييم بعد الحادث (AAR)؟",options:[{text:"24",correct:!1},{text:"48",correct:!1},{text:"72",correct:!0},{text:"168",correct:!1}],explanation:"خلال 72 ساعة — والذاكرة لا تزال حاضرة وكاملة."},{question:"ما نطاق الإشراف (Span of Control) في ICS؟",options:[{text:"شخصان (2)",correct:!1},{text:"3-7 أشخاص",correct:!0},{text:"10+ أشخاص",correct:!1},{text:"بلا حدود",correct:!1}],explanation:"وفقًا لـNIMS: 3-7 أشخاص لكل مشرف، والأمثل 5."}]}],t={lessons:e};export{t as default,e as lessons};
